insert into public.assessments (id,title,description,kind,competency,question_count,pass_percent,duration_seconds,max_attempts,cooldown_minutes,prerequisites,grants,status) values ('final-circuits','Évaluation : Circuits électriques','Évaluation de fin de module, corrigée par le serveur.','course_final','circuits',5,70,1200,null,30,array[]::text[],array[]::text[],'published') on conflict (id) do update set title=excluded.title, description=excluded.description, prerequisites=excluded.prerequisites, grants=excluded.grants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('circuits:ci-ohm','final-circuits','Loi d’Ohm','numeric','[{"prompt":"<p>Une résistance de 470 Ω est alimentée sous 12 V. Calculez le courant, <strong>en mA</strong>.</p>","unit":"mA","answer":{"value":25.53191489361702,"rel":0.02},"display":"25,53 mA","explanation":"<p>I = U/R = 12 / 470 = 25,53 mA.</p>"},{"prompt":"<p>Une résistance de 220 Ω est alimentée sous 5 V. Calculez le courant, <strong>en mA</strong>.</p>","unit":"mA","answer":{"value":22.727272727272727,"rel":0.02},"display":"22,73 mA","explanation":"<p>I = U/R = 5 / 220 = 22,73 mA.</p>"},{"prompt":"<p>Une résistance de 1 000 Ω est alimentée sous 9 V. Calculez le courant, <strong>en mA</strong>.</p>","unit":"mA","answer":{"value":9,"rel":0.02},"display":"9 mA","explanation":"<p>I = U/R = 9 / 1 000 = 9 mA.</p>"},{"prompt":"<p>Une résistance de 680 Ω est alimentée sous 24 V. Calculez le courant, <strong>en mA</strong>.</p>","unit":"mA","answer":{"value":35.294117647058826,"rel":0.02},"display":"35,29 mA","explanation":"<p>I = U/R = 24 / 680 = 35,29 mA.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('circuits:ci-par','final-circuits','Association de résistances','numeric','[{"prompt":"<p>Deux résistances de 100 Ω et 100 Ω sont en parallèle. Calculez la résistance équivalente, en Ω.</p>","unit":"Ω","answer":{"value":50,"rel":0.02},"display":"50 Ω","explanation":"<p>Req = R₁R₂/(R₁+R₂) = 50 Ω.</p>"},{"prompt":"<p>Deux résistances de 220 Ω et 330 Ω sont en parallèle. Calculez la résistance équivalente, en Ω.</p>","unit":"Ω","answer":{"value":132,"rel":0.02},"display":"132 Ω","explanation":"<p>Req = R₁R₂/(R₁+R₂) = 132 Ω.</p>"},{"prompt":"<p>Deux résistances de 1 000 Ω et 470 Ω sont en parallèle. Calculez la résistance équivalente, en Ω.</p>","unit":"Ω","answer":{"value":319.7278911564626,"rel":0.02},"display":"319,7 Ω","explanation":"<p>Req = R₁R₂/(R₁+R₂) = 319,7 Ω.</p>"},{"prompt":"<p>Deux résistances de 150 Ω et 680 Ω sont en parallèle. Calculez la résistance équivalente, en Ω.</p>","unit":"Ω","answer":{"value":122.89156626506025,"rel":0.02},"display":"122,9 Ω","explanation":"<p>Req = R₁R₂/(R₁+R₂) = 122,9 Ω.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('circuits:ci-div','final-circuits','Diviseur de tension','numeric','[{"prompt":"<p>Un diviseur à vide est alimenté sous 12 V, avec R₁ = 1 000 Ω côté source et R₂ = 2 200 Ω côté masse. Calculez la tension aux bornes de R₂, en V.</p>","unit":"V","answer":{"value":8.25,"rel":0.02},"display":"8,25 V","explanation":"<p>U₂ = E·R₂/(R₁+R₂) = 8,25 V.</p>"},{"prompt":"<p>Un diviseur à vide est alimenté sous 9 V, avec R₁ = 470 Ω côté source et R₂ = 470 Ω côté masse. Calculez la tension aux bornes de R₂, en V.</p>","unit":"V","answer":{"value":4.5,"rel":0.02},"display":"4,5 V","explanation":"<p>U₂ = E·R₂/(R₁+R₂) = 4,5 V.</p>"},{"prompt":"<p>Un diviseur à vide est alimenté sous 5 V, avec R₁ = 3 300 Ω côté source et R₂ = 1 000 Ω côté masse. Calculez la tension aux bornes de R₂, en V.</p>","unit":"V","answer":{"value":1.1627906976744187,"rel":0.02},"display":"1,163 V","explanation":"<p>U₂ = E·R₂/(R₁+R₂) = 1,163 V.</p>"},{"prompt":"<p>Un diviseur à vide est alimenté sous 24 V, avec R₁ = 10 000 Ω côté source et R₂ = 4 700 Ω côté masse. Calculez la tension aux bornes de R₂, en V.</p>","unit":"V","answer":{"value":7.673469387755102,"rel":0.02},"display":"7,673 V","explanation":"<p>U₂ = E·R₂/(R₁+R₂) = 7,673 V.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('circuits:ci-pow','final-circuits','Puissance','numeric','[{"prompt":"<p>Une résistance de 100 Ω est parcourue par 50 mA. Calculez la puissance dissipée, <strong>en mW</strong>.</p>","unit":"mW","answer":{"value":250,"rel":0.02},"display":"250 mW","explanation":"<p>P = R·I² = 250 mW.</p>"},{"prompt":"<p>Une résistance de 470 Ω est parcourue par 20 mA. Calculez la puissance dissipée, <strong>en mW</strong>.</p>","unit":"mW","answer":{"value":188,"rel":0.02},"display":"188 mW","explanation":"<p>P = R·I² = 188 mW.</p>"},{"prompt":"<p>Une résistance de 220 Ω est parcourue par 100 mA. Calculez la puissance dissipée, <strong>en mW</strong>.</p>","unit":"mW","answer":{"value":2200,"rel":0.02},"display":"2 200 mW","explanation":"<p>P = R·I² = 2 200 mW.</p>"},{"prompt":"<p>Une résistance de 1 000 Ω est parcourue par 10 mA. Calculez la puissance dissipée, <strong>en mW</strong>.</p>","unit":"mW","answer":{"value":100,"rel":0.02},"display":"100 mW","explanation":"<p>P = R·I² = 100 mW.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('circuits:ci-tau','final-circuits','Circuit RC','numeric','[{"prompt":"<p>Un circuit RC comporte R = 1 000 Ω et C = 100 µF. Calculez sa constante de temps, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":99.99999999999999,"rel":0.02},"display":"100 ms","explanation":"<p>τ = R·C = 100 ms. Le condensateur atteint environ 63 % de la tension finale après τ.</p>"},{"prompt":"<p>Un circuit RC comporte R = 4 700 Ω et C = 10 µF. Calculez sa constante de temps, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":46.99999999999999,"rel":0.02},"display":"47 ms","explanation":"<p>τ = R·C = 47 ms. Le condensateur atteint environ 63 % de la tension finale après τ.</p>"},{"prompt":"<p>Un circuit RC comporte R = 10 000 Ω et C = 47 µF. Calculez sa constante de temps, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":470,"rel":0.02},"display":"470 ms","explanation":"<p>τ = R·C = 470 ms. Le condensateur atteint environ 63 % de la tension finale après τ.</p>"},{"prompt":"<p>Un circuit RC comporte R = 2 200 Ω et C = 220 µF. Calculez sa constante de temps, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":483.99999999999994,"rel":0.02},"display":"484 ms","explanation":"<p>τ = R·C = 484 ms. Le condensateur atteint environ 63 % de la tension finale après τ.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('circuits:ci-depannage','final-circuits','Dépannage','qcm','[{"prompt":"<p>Scénario de dépannage : dans un diviseur alimenté en 12 V, vous mesurez 12 V au point milieu, alors que le calcul prévoit 6 V. Que soupçonnez-vous d’abord ?</p>","options":[{"id":"a","label":"R₂ (côté masse) est coupée, aucun courant ne circule"},{"id":"b","label":"R₂ (côté masse) est en court-circuit"},{"id":"c","label":"L’alimentation délivre une tension trop faible"},{"id":"d","label":"R₁ a une valeur deux fois trop grande"}],"answer":{"id":"a"},"display":"R₂ (côté masse) est coupée, aucun courant ne circule","explanation":"<p>Sans courant, la chute dans R₁ est nulle : le point milieu monte à la tension de l’alimentation. Un court-circuit de R₂ donnerait 0 V.</p>"},{"prompt":"<p>Scénario de dépannage : dans un diviseur alimenté en 12 V, vous mesurez 12 V au point milieu, alors que le calcul prévoit 6 V. Que soupçonnez-vous d’abord ?</p>","options":[{"id":"a","label":"R₂ (côté masse) est en court-circuit"},{"id":"b","label":"R₂ (côté masse) est coupée, aucun courant ne circule"},{"id":"c","label":"L’alimentation délivre une tension trop faible"},{"id":"d","label":"R₁ a une valeur deux fois trop grande"}],"answer":{"id":"b"},"display":"R₂ (côté masse) est coupée, aucun courant ne circule","explanation":"<p>Sans courant, la chute dans R₁ est nulle : le point milieu monte à la tension de l’alimentation. Un court-circuit de R₂ donnerait 0 V.</p>"},{"prompt":"<p>Scénario de dépannage : dans un diviseur alimenté en 12 V, vous mesurez 12 V au point milieu, alors que le calcul prévoit 6 V. Que soupçonnez-vous d’abord ?</p>","options":[{"id":"a","label":"R₂ (côté masse) est en court-circuit"},{"id":"b","label":"L’alimentation délivre une tension trop faible"},{"id":"c","label":"R₂ (côté masse) est coupée, aucun courant ne circule"},{"id":"d","label":"R₁ a une valeur deux fois trop grande"}],"answer":{"id":"c"},"display":"R₂ (côté masse) est coupée, aucun courant ne circule","explanation":"<p>Sans courant, la chute dans R₁ est nulle : le point milieu monte à la tension de l’alimentation. Un court-circuit de R₂ donnerait 0 V.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into public.assessments (id,title,description,kind,competency,question_count,pass_percent,duration_seconds,max_attempts,cooldown_minutes,prerequisites,grants,status) values ('final-signaux','Évaluation : Comprendre les signaux','Évaluation de fin de module, corrigée par le serveur.','course_final','signaux',5,70,1200,null,30,array[]::text[],array[]::text[],'published') on conflict (id) do update set title=excluded.title, description=excluded.description, prerequisites=excluded.prerequisites, grants=excluded.grants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('signaux:si-per','final-signaux','Période et fréquence','numeric','[{"prompt":"<p>Un signal sinusoïdal a une fréquence de 50 Hz. Calculez sa période, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":20,"rel":0.02},"display":"20 ms","explanation":"<p>T = 1/f = 20 ms.</p>"},{"prompt":"<p>Un signal sinusoïdal a une fréquence de 250 Hz. Calculez sa période, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":4,"rel":0.02},"display":"4 ms","explanation":"<p>T = 1/f = 4 ms.</p>"},{"prompt":"<p>Un signal sinusoïdal a une fréquence de 400 Hz. Calculez sa période, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":2.5,"rel":0.02},"display":"2,5 ms","explanation":"<p>T = 1/f = 2,5 ms.</p>"},{"prompt":"<p>Un signal sinusoïdal a une fréquence de 1 000 Hz. Calculez sa période, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":1,"rel":0.02},"display":"1 ms","explanation":"<p>T = 1/f = 1 ms.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('signaux:si-freq','final-signaux','Période et fréquence','numeric','[{"prompt":"<p>Sur l’oscilloscope, un cycle dure 2,5 ms. Calculez la fréquence, en Hz.</p>","unit":"Hz","answer":{"value":400,"rel":0.02},"display":"400 Hz","explanation":"<p>f = 1/T = 400 Hz.</p>"},{"prompt":"<p>Sur l’oscilloscope, un cycle dure 4 ms. Calculez la fréquence, en Hz.</p>","unit":"Hz","answer":{"value":250,"rel":0.02},"display":"250 Hz","explanation":"<p>f = 1/T = 250 Hz.</p>"},{"prompt":"<p>Sur l’oscilloscope, un cycle dure 8 ms. Calculez la fréquence, en Hz.</p>","unit":"Hz","answer":{"value":125,"rel":0.02},"display":"125 Hz","explanation":"<p>f = 1/T = 125 Hz.</p>"},{"prompt":"<p>Sur l’oscilloscope, un cycle dure 20 ms. Calculez la fréquence, en Hz.</p>","unit":"Hz","answer":{"value":50,"rel":0.02},"display":"50 Hz","explanation":"<p>f = 1/T = 50 Hz.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('signaux:si-puls','final-signaux','Pulsation','numeric','[{"prompt":"<p>Calculez la pulsation ω d’un signal de 50 Hz, en rad/s.</p>","unit":"rad/s","answer":{"value":314.1592653589793,"rel":0.02},"display":"314,2 rad/s","explanation":"<p>ω = 2πf = 314,2 rad/s.</p>"},{"prompt":"<p>Calculez la pulsation ω d’un signal de 100 Hz, en rad/s.</p>","unit":"rad/s","answer":{"value":628.3185307179587,"rel":0.02},"display":"628,3 rad/s","explanation":"<p>ω = 2πf = 628,3 rad/s.</p>"},{"prompt":"<p>Calculez la pulsation ω d’un signal de 159 Hz, en rad/s.</p>","unit":"rad/s","answer":{"value":999.0264638415542,"rel":0.02},"display":"999 rad/s","explanation":"<p>ω = 2πf = 999 rad/s.</p>"},{"prompt":"<p>Calculez la pulsation ω d’un signal de 500 Hz, en rad/s.</p>","unit":"rad/s","answer":{"value":3141.592653589793,"rel":0.02},"display":"3 142 rad/s","explanation":"<p>ω = 2πf = 3 142 rad/s.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('signaux:si-val','final-signaux','Lecture d’un signal','numeric','[{"prompt":"<p>Pour x(t) = 2 sin(2π · 100 · t), calculez x à t = 1,25 ms, en volts.</p>","unit":"V","answer":{"value":1.414213562373095,"abs":0.03},"display":"1,414 V","explanation":"<p>x = 2 · sin(2π · 100 · 0,00125) = 1,414 V.</p>"},{"prompt":"<p>Pour x(t) = 4 sin(2π · 50 · t), calculez x à t = 2,5 ms, en volts.</p>","unit":"V","answer":{"value":2.82842712474619,"abs":0.03},"display":"2,828 V","explanation":"<p>x = 4 · sin(2π · 50 · 0,0025) = 2,828 V.</p>"},{"prompt":"<p>Pour x(t) = 3 sin(2π · 200 · t), calculez x à t = 0,5 ms, en volts.</p>","unit":"V","answer":{"value":1.7633557568774194,"abs":0.03},"display":"1,763 V","explanation":"<p>x = 3 · sin(2π · 200 · 0,0005) = 1,763 V.</p>"},{"prompt":"<p>Pour x(t) = 5 sin(2π · 125 · t), calculez x à t = 1 ms, en volts.</p>","unit":"V","answer":{"value":3.5355339059327373,"abs":0.03},"display":"3,536 V","explanation":"<p>x = 5 · sin(2π · 125 · 0,001) = 3,536 V.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('signaux:si-shift','final-signaux','Phase','numeric','[{"prompt":"<p>Un signal de 50 Hz présente une phase de 90°. Calculez son avance dans le temps, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":5,"rel":0.02},"display":"5 ms","explanation":"<p>Δt = φ/(2πf) = 5 ms.</p>"},{"prompt":"<p>Un signal de 100 Hz présente une phase de 180°. Calculez son avance dans le temps, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":5,"rel":0.02},"display":"5 ms","explanation":"<p>Δt = φ/(2πf) = 5 ms.</p>"},{"prompt":"<p>Un signal de 250 Hz présente une phase de 45°. Calculez son avance dans le temps, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":0.5,"rel":0.02},"display":"0,5 ms","explanation":"<p>Δt = φ/(2πf) = 0,5 ms.</p>"},{"prompt":"<p>Un signal de 500 Hz présente une phase de 90°. Calculez son avance dans le temps, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":0.5,"rel":0.02},"display":"0,5 ms","explanation":"<p>Δt = φ/(2πf) = 0,5 ms.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('signaux:si-amp','final-signaux','Grandeurs d’un signal','qcm','[{"prompt":"<p>Vous doublez la fréquence d’une sinusoïde sans changer son amplitude. Que devient sa période ?</p>","options":[{"id":"a","label":"Elle est divisée par deux"},{"id":"b","label":"Elle double"},{"id":"c","label":"Elle ne change pas"},{"id":"d","label":"Elle est multipliée par quatre"}],"answer":{"id":"a"},"display":"Elle est divisée par deux","explanation":"<p>T = 1/f : la période varie à l’inverse de la fréquence.</p>"},{"prompt":"<p>Vous doublez la fréquence d’une sinusoïde sans changer son amplitude. Que devient sa période ?</p>","options":[{"id":"a","label":"Elle double"},{"id":"b","label":"Elle est divisée par deux"},{"id":"c","label":"Elle ne change pas"},{"id":"d","label":"Elle est multipliée par quatre"}],"answer":{"id":"b"},"display":"Elle est divisée par deux","explanation":"<p>T = 1/f : la période varie à l’inverse de la fréquence.</p>"},{"prompt":"<p>Vous doublez la fréquence d’une sinusoïde sans changer son amplitude. Que devient sa période ?</p>","options":[{"id":"a","label":"Elle double"},{"id":"b","label":"Elle ne change pas"},{"id":"c","label":"Elle est divisée par deux"},{"id":"d","label":"Elle est multipliée par quatre"}],"answer":{"id":"c"},"display":"Elle est divisée par deux","explanation":"<p>T = 1/f : la période varie à l’inverse de la fréquence.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into public.assessments (id,title,description,kind,competency,question_count,pass_percent,duration_seconds,max_attempts,cooldown_minutes,prerequisites,grants,status) values ('final-ondes-em','Évaluation : Ondes électromagnétiques','Évaluation de fin de module, corrigée par le serveur.','course_final','ondes-em',5,70,1200,null,30,array['signaux']::text[],array[]::text[],'published') on conflict (id) do update set title=excluded.title, description=excluded.description, prerequisites=excluded.prerequisites, grants=excluded.grants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ondes-em:em-lam','final-ondes-em','Longueur d’onde','numeric','[{"prompt":"<p>Calculez la longueur d’onde dans le vide d’une onde de 100 MHz, <strong>en cm</strong>.</p>","unit":"cm","answer":{"value":299.792458,"rel":0.02},"display":"299,8 cm","explanation":"<p>λ = c/f = 299,8 cm.</p>"},{"prompt":"<p>Calculez la longueur d’onde dans le vide d’une onde de 900 MHz, <strong>en cm</strong>.</p>","unit":"cm","answer":{"value":33.31027311111111,"rel":0.02},"display":"33,31 cm","explanation":"<p>λ = c/f = 33,31 cm.</p>"},{"prompt":"<p>Calculez la longueur d’onde dans le vide d’une onde de 2 400 MHz, <strong>en cm</strong>.</p>","unit":"cm","answer":{"value":12.491352416666667,"rel":0.02},"display":"12,49 cm","explanation":"<p>λ = c/f = 12,49 cm.</p>"},{"prompt":"<p>Calculez la longueur d’onde dans le vide d’une onde de 5 000 MHz, <strong>en cm</strong>.</p>","unit":"cm","answer":{"value":5.99584916,"rel":0.02},"display":"5,996 cm","explanation":"<p>λ = c/f = 5,996 cm.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ondes-em:em-coax','final-ondes-em','Vitesse dans un milieu','numeric','[{"prompt":"<p>Dans un câble de facteur de vitesse 0,66, calculez la longueur d’onde à 100 MHz, en mètres.</p>","unit":"m","answer":{"value":1.9786302228000001,"rel":0.02},"display":"1,979 m","explanation":"<p>λ = VF·c/f = 1,979 m.</p>"},{"prompt":"<p>Dans un câble de facteur de vitesse 0,66, calculez la longueur d’onde à 145 MHz, en mètres.</p>","unit":"m","answer":{"value":1.3645725674482758,"rel":0.02},"display":"1,365 m","explanation":"<p>λ = VF·c/f = 1,365 m.</p>"},{"prompt":"<p>Dans un câble de facteur de vitesse 0,85, calculez la longueur d’onde à 433 MHz, en mètres.</p>","unit":"m","answer":{"value":0.5885071346420323,"rel":0.02},"display":"0,5885 m","explanation":"<p>λ = VF·c/f = 0,5885 m.</p>"},{"prompt":"<p>Dans un câble de facteur de vitesse 0,85, calculez la longueur d’onde à 1 000 MHz, en mètres.</p>","unit":"m","answer":{"value":0.2548235893,"rel":0.02},"display":"0,2548 m","explanation":"<p>λ = VF·c/f = 0,2548 m.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ondes-em:em-freq','final-ondes-em','Longueur d’onde','numeric','[{"prompt":"<p>Une onde a une longueur d’onde de 3 m dans le vide. Calculez sa fréquence, <strong>en MHz</strong>.</p>","unit":"MHz","answer":{"value":99.93081933333333,"rel":0.02},"display":"99,93 MHz","explanation":"<p>f = c/λ = 99,93 MHz.</p>"},{"prompt":"<p>Une onde a une longueur d’onde de 0,33 m dans le vide. Calculez sa fréquence, <strong>en MHz</strong>.</p>","unit":"MHz","answer":{"value":908.4619939393939,"rel":0.02},"display":"908,5 MHz","explanation":"<p>f = c/λ = 908,5 MHz.</p>"},{"prompt":"<p>Une onde a une longueur d’onde de 0,125 m dans le vide. Calculez sa fréquence, <strong>en MHz</strong>.</p>","unit":"MHz","answer":{"value":2398.339664,"rel":0.02},"display":"2 398 MHz","explanation":"<p>f = c/λ = 2 398 MHz.</p>"},{"prompt":"<p>Une onde a une longueur d’onde de 0,06 m dans le vide. Calculez sa fréquence, <strong>en MHz</strong>.</p>","unit":"MHz","answer":{"value":4996.540966666667,"rel":0.02},"display":"4 997 MHz","explanation":"<p>f = c/λ = 4 997 MHz.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ondes-em:em-time','final-ondes-em','Vitesse dans un milieu','numeric','[{"prompt":"<p>Combien de temps une onde met-elle pour parcourir 3 000 m dans le vide ? Réponse <strong>en µs</strong>.</p>","unit":"µs","answer":{"value":10.00692285594456,"rel":0.02},"display":"10,01 µs","explanation":"<p>t = d/c = 10,01 µs.</p>"},{"prompt":"<p>Combien de temps une onde met-elle pour parcourir 36 000 m dans le vide ? Réponse <strong>en µs</strong>.</p>","unit":"µs","answer":{"value":120.08307427133474,"rel":0.02},"display":"120,1 µs","explanation":"<p>t = d/c = 120,1 µs.</p>"},{"prompt":"<p>Combien de temps une onde met-elle pour parcourir 150 m dans le vide ? Réponse <strong>en µs</strong>.</p>","unit":"µs","answer":{"value":0.500346142797228,"rel":0.02},"display":"0,5003 µs","explanation":"<p>t = d/c = 0,5003 µs.</p>"},{"prompt":"<p>Combien de temps une onde met-elle pour parcourir 1 200 m dans le vide ? Réponse <strong>en µs</strong>.</p>","unit":"µs","answer":{"value":4.002769142377824,"rel":0.02},"display":"4,003 µs","explanation":"<p>t = d/c = 4,003 µs.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ondes-em:em-band','final-ondes-em','Bandes de fréquences','qcm','[{"prompt":"<p>À quelle bande de l’UIT appartient une fréquence de 100 MHz ?</p>","options":[{"id":"a","label":"VHF"},{"id":"b","label":"UHF"},{"id":"c","label":"SHF"},{"id":"d","label":"MF"}],"answer":{"id":"a"},"display":"VHF","explanation":"<p>VHF : ondes métriques.</p>"},{"prompt":"<p>À quelle bande de l’UIT appartient une fréquence de 900 MHz ?</p>","options":[{"id":"a","label":"VHF"},{"id":"b","label":"UHF"},{"id":"c","label":"SHF"},{"id":"d","label":"MF"}],"answer":{"id":"b"},"display":"UHF","explanation":"<p>UHF : ondes décimétriques.</p>"},{"prompt":"<p>À quelle bande de l’UIT appartient une fréquence de 5 000 MHz ?</p>","options":[{"id":"a","label":"VHF"},{"id":"b","label":"UHF"},{"id":"c","label":"SHF"},{"id":"d","label":"MF"}],"answer":{"id":"c"},"display":"SHF","explanation":"<p>SHF : ondes centimétriques.</p>"},{"prompt":"<p>À quelle bande de l’UIT appartient une fréquence de 1 MHz ?</p>","options":[{"id":"a","label":"VHF"},{"id":"b","label":"UHF"},{"id":"c","label":"SHF"},{"id":"d","label":"MF"}],"answer":{"id":"d"},"display":"MF","explanation":"<p>MF : ondes hectométriques (ondes moyennes).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ondes-em:em-relation','final-ondes-em','Longueur d’onde','qcm','[{"prompt":"<p>Une onde de fréquence fixe passe du vide dans un câble coaxial. Que se passe-t-il ?</p>","options":[{"id":"a","label":"La fréquence reste la même, la longueur d’onde diminue"},{"id":"b","label":"La fréquence diminue, la longueur d’onde reste la même"},{"id":"c","label":"Les deux diminuent"},{"id":"d","label":"Les deux augmentent"}],"answer":{"id":"a"},"display":"La fréquence reste la même, la longueur d’onde diminue","explanation":"<p>La fréquence est imposée par la source. La vitesse baisse, donc λ = v/f baisse.</p>"},{"prompt":"<p>Une onde de fréquence fixe passe du vide dans un câble coaxial. Que se passe-t-il ?</p>","options":[{"id":"a","label":"La fréquence diminue, la longueur d’onde reste la même"},{"id":"b","label":"La fréquence reste la même, la longueur d’onde diminue"},{"id":"c","label":"Les deux diminuent"},{"id":"d","label":"Les deux augmentent"}],"answer":{"id":"b"},"display":"La fréquence reste la même, la longueur d’onde diminue","explanation":"<p>La fréquence est imposée par la source. La vitesse baisse, donc λ = v/f baisse.</p>"},{"prompt":"<p>Une onde de fréquence fixe passe du vide dans un câble coaxial. Que se passe-t-il ?</p>","options":[{"id":"a","label":"La fréquence diminue, la longueur d’onde reste la même"},{"id":"b","label":"Les deux diminuent"},{"id":"c","label":"La fréquence reste la même, la longueur d’onde diminue"},{"id":"d","label":"Les deux augmentent"}],"answer":{"id":"c"},"display":"La fréquence reste la même, la longueur d’onde diminue","explanation":"<p>La fréquence est imposée par la source. La vitesse baisse, donc λ = v/f baisse.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into public.assessments (id,title,description,kind,competency,question_count,pass_percent,duration_seconds,max_attempts,cooldown_minutes,prerequisites,grants,status) values ('final-antennes','Évaluation : Antennes','Évaluation de fin de module, corrigée par le serveur.','course_final','antennes',5,70,1200,null,30,array['ondes-em']::text[],array[]::text[],'published') on conflict (id) do update set title=excluded.title, description=excluded.description, prerequisites=excluded.prerequisites, grants=excluded.grants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('antennes:an-dip','final-antennes','Dimensionner un dipôle','numeric','[{"prompt":"<p>Calculez la longueur théorique d’un dipôle demi-onde à 100 MHz, <strong>en cm</strong> (facteur de raccourcissement ignoré).</p>","unit":"cm","answer":{"value":149.896229,"rel":0.02},"display":"149,9 cm","explanation":"<p>L = λ/2 = c/(2f) = 149,9 cm.</p>"},{"prompt":"<p>Calculez la longueur théorique d’un dipôle demi-onde à 145 MHz, <strong>en cm</strong> (facteur de raccourcissement ignoré).</p>","unit":"cm","answer":{"value":103.3767096551724,"rel":0.02},"display":"103,4 cm","explanation":"<p>L = λ/2 = c/(2f) = 103,4 cm.</p>"},{"prompt":"<p>Calculez la longueur théorique d’un dipôle demi-onde à 433 MHz, <strong>en cm</strong> (facteur de raccourcissement ignoré).</p>","unit":"cm","answer":{"value":34.61806674364896,"rel":0.02},"display":"34,62 cm","explanation":"<p>L = λ/2 = c/(2f) = 34,62 cm.</p>"},{"prompt":"<p>Calculez la longueur théorique d’un dipôle demi-onde à 900 MHz, <strong>en cm</strong> (facteur de raccourcissement ignoré).</p>","unit":"cm","answer":{"value":16.655136555555554,"rel":0.02},"display":"16,66 cm","explanation":"<p>L = λ/2 = c/(2f) = 16,66 cm.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('antennes:an-db','final-antennes','Gain','numeric','[{"prompt":"<p>Une antenne a un gain de 2 en rapport linéaire. Exprimez-le en dBi.</p>","unit":"dBi","answer":{"value":3.010299956639812,"abs":0.15},"display":"3,01 dBi","explanation":"<p>G = 10 log₁₀(2) = 3,01 dBi.</p>"},{"prompt":"<p>Une antenne a un gain de 4 en rapport linéaire. Exprimez-le en dBi.</p>","unit":"dBi","answer":{"value":6.020599913279624,"abs":0.15},"display":"6,021 dBi","explanation":"<p>G = 10 log₁₀(4) = 6,021 dBi.</p>"},{"prompt":"<p>Une antenne a un gain de 10 en rapport linéaire. Exprimez-le en dBi.</p>","unit":"dBi","answer":{"value":10,"abs":0.15},"display":"10 dBi","explanation":"<p>G = 10 log₁₀(10) = 10 dBi.</p>"},{"prompt":"<p>Une antenne a un gain de 50 en rapport linéaire. Exprimez-le en dBi.</p>","unit":"dBi","answer":{"value":16.989700043360187,"abs":0.15},"display":"16,99 dBi","explanation":"<p>G = 10 log₁₀(50) = 16,99 dBi.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('antennes:an-area','final-antennes','Surface effective','numeric','[{"prompt":"<p>Calculez la surface effective d’une antenne de gain linéaire 1,64 à 0,9 GHz, <strong>en cm²</strong>.</p>","unit":"cm²","answer":{"value":144.8072716627551,"rel":0.02},"display":"144,8 cm²","explanation":"<p>Ae = G·λ²/(4π) = 144,8 cm².</p>"},{"prompt":"<p>Calculez la surface effective d’une antenne de gain linéaire 10 à 2,4 GHz, <strong>en cm²</strong>.</p>","unit":"cm²","answer":{"value":124.16782059496911,"rel":0.02},"display":"124,2 cm²","explanation":"<p>Ae = G·λ²/(4π) = 124,2 cm².</p>"},{"prompt":"<p>Calculez la surface effective d’une antenne de gain linéaire 4 à 1,8 GHz, <strong>en cm²</strong>.</p>","unit":"cm²","answer":{"value":88.29711686753359,"rel":0.02},"display":"88,3 cm²","explanation":"<p>Ae = G·λ²/(4π) = 88,3 cm².</p>"},{"prompt":"<p>Calculez la surface effective d’une antenne de gain linéaire 31,6 à 5 GHz, <strong>en cm²</strong>.</p>","unit":"cm²","answer":{"value":90.40212013365561,"rel":0.02},"display":"90,4 cm²","explanation":"<p>Ae = G·λ²/(4π) = 90,4 cm².</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('antennes:an-pol','final-antennes','Polarisation','numeric','[{"prompt":"<p>Deux antennes à polarisation linéaire sont désalignées de 0°. Quelle fraction de la puissance est captée ? Réponse <strong>en %</strong>.</p>","unit":"%","answer":{"value":100,"abs":1},"display":"100 %","explanation":"<p>Fraction = cos²(0°) = 100 %.</p>"},{"prompt":"<p>Deux antennes à polarisation linéaire sont désalignées de 30°. Quelle fraction de la puissance est captée ? Réponse <strong>en %</strong>.</p>","unit":"%","answer":{"value":75.00000000000001,"abs":1},"display":"75 %","explanation":"<p>Fraction = cos²(30°) = 75 %.</p>"},{"prompt":"<p>Deux antennes à polarisation linéaire sont désalignées de 45°. Quelle fraction de la puissance est captée ? Réponse <strong>en %</strong>.</p>","unit":"%","answer":{"value":50.000000000000014,"abs":1},"display":"50 %","explanation":"<p>Fraction = cos²(45°) = 50 %.</p>"},{"prompt":"<p>Deux antennes à polarisation linéaire sont désalignées de 60°. Quelle fraction de la puissance est captée ? Réponse <strong>en %</strong>.</p>","unit":"%","answer":{"value":25.00000000000001,"abs":1},"display":"25 %","explanation":"<p>Fraction = cos²(60°) = 25 %.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('antennes:an-array','final-antennes','Réseaux d’antennes','qcm','[{"prompt":"<p>Dans un réseau d’antennes, que produit un déphasage progressif entre les éléments ?</p>","options":[{"id":"a","label":"Il oriente le lobe principal"},{"id":"b","label":"Il augmente la fréquence émise"},{"id":"c","label":"Il supprime les pertes du câble"},{"id":"d","label":"Il change la polarisation en circulaire"}],"answer":{"id":"a"},"display":"Il oriente le lobe principal","explanation":"<p>Le déphasage décale la direction où les contributions s’ajoutent en phase : c’est le dépointage électronique.</p>"},{"prompt":"<p>Dans un réseau d’antennes, que produit un déphasage progressif entre les éléments ?</p>","options":[{"id":"a","label":"Il augmente la fréquence émise"},{"id":"b","label":"Il oriente le lobe principal"},{"id":"c","label":"Il supprime les pertes du câble"},{"id":"d","label":"Il change la polarisation en circulaire"}],"answer":{"id":"b"},"display":"Il oriente le lobe principal","explanation":"<p>Le déphasage décale la direction où les contributions s’ajoutent en phase : c’est le dépointage électronique.</p>"},{"prompt":"<p>Dans un réseau d’antennes, que produit un déphasage progressif entre les éléments ?</p>","options":[{"id":"a","label":"Il augmente la fréquence émise"},{"id":"b","label":"Il supprime les pertes du câble"},{"id":"c","label":"Il oriente le lobe principal"},{"id":"d","label":"Il change la polarisation en circulaire"}],"answer":{"id":"c"},"display":"Il oriente le lobe principal","explanation":"<p>Le déphasage décale la direction où les contributions s’ajoutent en phase : c’est le dépointage électronique.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into public.assessments (id,title,description,kind,competency,question_count,pass_percent,duration_seconds,max_attempts,cooldown_minutes,prerequisites,grants,status) values ('final-propagation','Évaluation : Propagation radio','Évaluation de fin de module, corrigée par le serveur.','course_final','propagation',5,70,1200,null,30,array['ondes-em']::text[],array[]::text[],'published') on conflict (id) do update set title=excluded.title, description=excluded.description, prerequisites=excluded.prerequisites, grants=excluded.grants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('propagation:pr-fspl','final-propagation','Espace libre','numeric','[{"prompt":"<p>Calculez la perte en espace libre sur 1 km à 900 MHz, en dB.</p>","unit":"dB","answer":{"value":91.53263341066986,"abs":0.5},"display":"91,53 dB","explanation":"<p>FSPL = 20 log₁₀(4πdf/c) = 91,53 dB.</p>"},{"prompt":"<p>Calculez la perte en espace libre sur 5 km à 2 400 MHz, en dB.</p>","unit":"dB","answer":{"value":114.03140814283586,"abs":0.5},"display":"114 dB","explanation":"<p>FSPL = 20 log₁₀(4πdf/c) = 114 dB.</p>"},{"prompt":"<p>Calculez la perte en espace libre sur 10 km à 100 MHz, en dB.</p>","unit":"dB","answer":{"value":92.44778322188337,"abs":0.5},"display":"92,45 dB","explanation":"<p>FSPL = 20 log₁₀(4πdf/c) = 92,45 dB.</p>"},{"prompt":"<p>Calculez la perte en espace libre sur 0,2 km à 5 000 MHz, en dB.</p>","unit":"dB","answer":{"value":92.44778322188337,"abs":0.5},"display":"92,45 dB","explanation":"<p>FSPL = 20 log₁₀(4πdf/c) = 92,45 dB.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('propagation:pr-budget','final-propagation','Bilan de liaison','numeric','[{"prompt":"<p>Puissance émise 30 dBm, gains d’antennes 10 dBi et 2 dBi, perte de trajet 110 dB. Calculez la puissance reçue, en dBm.</p>","unit":"dBm","answer":{"value":-68,"abs":0.1},"display":"−68 dBm","explanation":"<p>Pr = Pe + Ge + Gr − L = −68 dBm.</p>"},{"prompt":"<p>Puissance émise 20 dBm, gains d’antennes 6 dBi et 6 dBi, perte de trajet 95 dB. Calculez la puissance reçue, en dBm.</p>","unit":"dBm","answer":{"value":-63,"abs":0.1},"display":"−63 dBm","explanation":"<p>Pr = Pe + Ge + Gr − L = −63 dBm.</p>"},{"prompt":"<p>Puissance émise 43 dBm, gains d’antennes 15 dBi et 0 dBi, perte de trajet 130 dB. Calculez la puissance reçue, en dBm.</p>","unit":"dBm","answer":{"value":-72,"abs":0.1},"display":"−72 dBm","explanation":"<p>Pr = Pe + Ge + Gr − L = −72 dBm.</p>"},{"prompt":"<p>Puissance émise 10 dBm, gains d’antennes 3 dBi et 3 dBi, perte de trajet 80 dB. Calculez la puissance reçue, en dBm.</p>","unit":"dBm","answer":{"value":-64,"abs":0.1},"display":"−64 dBm","explanation":"<p>Pr = Pe + Ge + Gr − L = −64 dBm.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('propagation:pr-horizon','final-propagation','Horizon radio','numeric','[{"prompt":"<p>Avec des antennes à 30 m et 1,5 m (modèle 4/3 de la Terre), calculez l’horizon radio, <strong>en km</strong>.</p>","unit":"km","answer":{"value":27.612118239346188,"rel":0.03},"display":"27,61 km","explanation":"<p>d ≈ 4,12(√h₁ + √h₂) = 27,61 km.</p>"},{"prompt":"<p>Avec des antennes à 50 m et 10 m (modèle 4/3 de la Terre), calculez l’horizon radio, <strong>en km</strong>.</p>","unit":"km","answer":{"value":42.16138334477948,"rel":0.03},"display":"42,16 km","explanation":"<p>d ≈ 4,12(√h₁ + √h₂) = 42,16 km.</p>"},{"prompt":"<p>Avec des antennes à 100 m et 2 m (modèle 4/3 de la Terre), calculez l’horizon radio, <strong>en km</strong>.</p>","unit":"km","answer":{"value":47.02655987697715,"rel":0.03},"display":"47,03 km","explanation":"<p>d ≈ 4,12(√h₁ + √h₂) = 47,03 km.</p>"},{"prompt":"<p>Avec des antennes à 20 m et 20 m (modèle 4/3 de la Terre), calculez l’horizon radio, <strong>en km</strong>.</p>","unit":"km","answer":{"value":36.850400269196534,"rel":0.03},"display":"36,85 km","explanation":"<p>d ≈ 4,12(√h₁ + √h₂) = 36,85 km.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('propagation:pr-fresnel','final-propagation','Zone de Fresnel','numeric','[{"prompt":"<p>À 900 MHz, un obstacle se trouve à 1 000 m de l’émetteur et 1 000 m du récepteur. Calculez le rayon de la première zone de Fresnel, en mètres.</p>","unit":"m","answer":{"value":12.90547812192774,"rel":0.03},"display":"12,91 m","explanation":"<p>r = √(λ·d₁·d₂/(d₁+d₂)) = 12,91 m.</p>"},{"prompt":"<p>À 2 400 MHz, un obstacle se trouve à 500 m de l’émetteur et 1 500 m du récepteur. Calculez le rayon de la première zone de Fresnel, en mètres.</p>","unit":"m","answer":{"value":6.844163320852301,"rel":0.03},"display":"6,844 m","explanation":"<p>r = √(λ·d₁·d₂/(d₁+d₂)) = 6,844 m.</p>"},{"prompt":"<p>À 5 000 MHz, un obstacle se trouve à 2 000 m de l’émetteur et 2 000 m du récepteur. Calculez le rayon de la première zone de Fresnel, en mètres.</p>","unit":"m","answer":{"value":7.743286873156644,"rel":0.03},"display":"7,743 m","explanation":"<p>r = √(λ·d₁·d₂/(d₁+d₂)) = 7,743 m.</p>"},{"prompt":"<p>À 100 MHz, un obstacle se trouve à 5 000 m de l’émetteur et 5 000 m du récepteur. Calculez le rayon de la première zone de Fresnel, en mètres.</p>","unit":"m","answer":{"value":86.57257908830023,"rel":0.03},"display":"86,57 m","explanation":"<p>r = √(λ·d₁·d₂/(d₁+d₂)) = 86,57 m.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('propagation:pr-double','final-propagation','Espace libre','qcm','[{"prompt":"<p>En espace libre, on double la distance. De combien varie la perte de trajet ?</p>","options":[{"id":"a","label":"+6 dB"},{"id":"b","label":"+3 dB"},{"id":"c","label":"+12 dB"},{"id":"d","label":"+20 dB"}],"answer":{"id":"a"},"display":"+6 dB","explanation":"<p>La perte varie en 20 log₁₀(d) : doubler d ajoute 20 log₁₀(2) ≈ 6 dB.</p>"},{"prompt":"<p>En espace libre, on double la distance. De combien varie la perte de trajet ?</p>","options":[{"id":"a","label":"+3 dB"},{"id":"b","label":"+6 dB"},{"id":"c","label":"+12 dB"},{"id":"d","label":"+20 dB"}],"answer":{"id":"b"},"display":"+6 dB","explanation":"<p>La perte varie en 20 log₁₀(d) : doubler d ajoute 20 log₁₀(2) ≈ 6 dB.</p>"},{"prompt":"<p>En espace libre, on double la distance. De combien varie la perte de trajet ?</p>","options":[{"id":"a","label":"+3 dB"},{"id":"b","label":"+12 dB"},{"id":"c","label":"+6 dB"},{"id":"d","label":"+20 dB"}],"answer":{"id":"c"},"display":"+6 dB","explanation":"<p>La perte varie en 20 log₁₀(d) : doubler d ajoute 20 log₁₀(2) ≈ 6 dB.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into public.assessments (id,title,description,kind,competency,question_count,pass_percent,duration_seconds,max_attempts,cooldown_minutes,prerequisites,grants,status) values ('final-chaine','Évaluation : Chaîne de transmission','Évaluation de fin de module, corrigée par le serveur.','course_final','chaine',5,70,1200,null,30,array['signaux']::text[],array[]::text[],'published') on conflict (id) do update set title=excluded.title, description=excluded.description, prerequisites=excluded.prerequisites, grants=excluded.grants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('chaine:ch-db','final-chaine','Décibels','numeric','[{"prompt":"<p>Un rapport signal sur bruit vaut 3 dB. Donnez-le en rapport linéaire.</p>","unit":"","answer":{"value":1.9952623149688795,"rel":0.02},"display":"1,995","explanation":"<p>10^(3/10) = 1,995.</p>"},{"prompt":"<p>Un rapport signal sur bruit vaut 10 dB. Donnez-le en rapport linéaire.</p>","unit":"","answer":{"value":10,"rel":0.02},"display":"10","explanation":"<p>10^(10/10) = 10.</p>"},{"prompt":"<p>Un rapport signal sur bruit vaut 20 dB. Donnez-le en rapport linéaire.</p>","unit":"","answer":{"value":100,"rel":0.02},"display":"100","explanation":"<p>10^(20/10) = 100.</p>"},{"prompt":"<p>Un rapport signal sur bruit vaut 13 dB. Donnez-le en rapport linéaire.</p>","unit":"","answer":{"value":19.952623149688797,"rel":0.02},"display":"19,95","explanation":"<p>10^(13/10) = 19,95.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('chaine:ch-shannon','final-chaine','Capacité de Shannon','numeric','[{"prompt":"<p>Calculez la capacité de Shannon d’un canal de 1 MHz avec un RSB de 10 dB, <strong>en Mbit/s</strong>.</p>","unit":"Mbit/s","answer":{"value":3.4594316186372973,"rel":0.02},"display":"3,459 Mbit/s","explanation":"<p>C = B log₂(1 + RSB) = 3,459 Mbit/s.</p>"},{"prompt":"<p>Calculez la capacité de Shannon d’un canal de 20 MHz avec un RSB de 20 dB, <strong>en Mbit/s</strong>.</p>","unit":"Mbit/s","answer":{"value":133.1642296550359,"rel":0.02},"display":"133,2 Mbit/s","explanation":"<p>C = B log₂(1 + RSB) = 133,2 Mbit/s.</p>"},{"prompt":"<p>Calculez la capacité de Shannon d’un canal de 5 MHz avec un RSB de 15 dB, <strong>en Mbit/s</strong>.</p>","unit":"Mbit/s","answer":{"value":25.139038366752597,"rel":0.02},"display":"25,14 Mbit/s","explanation":"<p>C = B log₂(1 + RSB) = 25,14 Mbit/s.</p>"},{"prompt":"<p>Calculez la capacité de Shannon d’un canal de 0,1 MHz avec un RSB de 30 dB, <strong>en Mbit/s</strong>.</p>","unit":"Mbit/s","answer":{"value":0.9967226258835993,"rel":0.02},"display":"0,9967 Mbit/s","explanation":"<p>C = B log₂(1 + RSB) = 0,9967 Mbit/s.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('chaine:ch-noise','final-chaine','Bruit thermique','numeric','[{"prompt":"<p>Calculez la puissance de bruit thermique dans 1 MHz à 290 K, en dBm.</p>","unit":"dBm","answer":{"value":-113.97518719422811,"abs":0.5},"display":"−114 dBm","explanation":"<p>N = kTB, soit environ −174 + 10 log₁₀(B) = −114 dBm.</p>"},{"prompt":"<p>Calculez la puissance de bruit thermique dans 20 MHz à 290 K, en dBm.</p>","unit":"dBm","answer":{"value":-100.9648872375883,"abs":0.5},"display":"−101 dBm","explanation":"<p>N = kTB, soit environ −174 + 10 log₁₀(B) = −101 dBm.</p>"},{"prompt":"<p>Calculez la puissance de bruit thermique dans 0,2 MHz à 290 K, en dBm.</p>","unit":"dBm","answer":{"value":-120.9648872375883,"abs":0.5},"display":"−121 dBm","explanation":"<p>N = kTB, soit environ −174 + 10 log₁₀(B) = −121 dBm.</p>"},{"prompt":"<p>Calculez la puissance de bruit thermique dans 100 MHz à 290 K, en dBm.</p>","unit":"dBm","answer":{"value":-93.97518719422811,"abs":0.5},"display":"−93,98 dBm","explanation":"<p>N = kTB, soit environ −174 + 10 log₁₀(B) = −93,98 dBm.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('chaine:ch-rep','final-chaine','Codage de canal','numeric','[{"prompt":"<p>Avec un code à répétition ×3, combien de bits sont transmis pour 100 bits utiles ?</p>","unit":"bits","answer":{"value":300,"abs":0.5},"display":"300 bits","explanation":"<p>Rendement 1/3 : 100 × 3 = 300 bits.</p>"},{"prompt":"<p>Avec un code à répétition ×3, combien de bits sont transmis pour 8 bits utiles ?</p>","unit":"bits","answer":{"value":24,"abs":0.5},"display":"24 bits","explanation":"<p>Rendement 1/3 : 8 × 3 = 24 bits.</p>"},{"prompt":"<p>Avec un code à répétition ×3, combien de bits sont transmis pour 1 000 bits utiles ?</p>","unit":"bits","answer":{"value":3000,"abs":0.5},"display":"3 000 bits","explanation":"<p>Rendement 1/3 : 1 000 × 3 = 3 000 bits.</p>"},{"prompt":"<p>Avec un code à répétition ×3, combien de bits sont transmis pour 56 bits utiles ?</p>","unit":"bits","answer":{"value":168,"abs":0.5},"display":"168 bits","explanation":"<p>Rendement 1/3 : 56 × 3 = 168 bits.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('chaine:ch-ordre','final-chaine','Chaîne de transmission','qcm','[{"prompt":"<p>À l’émission, dans quel ordre s’enchaînent les étapes ?</p>","options":[{"id":"a","label":"Source, codage, modulation, canal"},{"id":"b","label":"Modulation, source, codage, canal"},{"id":"c","label":"Source, modulation, canal, codage"},{"id":"d","label":"Canal, codage, modulation, source"}],"answer":{"id":"a"},"display":"Source, codage, modulation, canal","explanation":"<p>Le message est d’abord codé, puis le signal modulé est envoyé dans le canal.</p>"},{"prompt":"<p>À l’émission, dans quel ordre s’enchaînent les étapes ?</p>","options":[{"id":"a","label":"Modulation, source, codage, canal"},{"id":"b","label":"Source, codage, modulation, canal"},{"id":"c","label":"Source, modulation, canal, codage"},{"id":"d","label":"Canal, codage, modulation, source"}],"answer":{"id":"b"},"display":"Source, codage, modulation, canal","explanation":"<p>Le message est d’abord codé, puis le signal modulé est envoyé dans le canal.</p>"},{"prompt":"<p>À l’émission, dans quel ordre s’enchaînent les étapes ?</p>","options":[{"id":"a","label":"Modulation, source, codage, canal"},{"id":"b","label":"Source, modulation, canal, codage"},{"id":"c","label":"Source, codage, modulation, canal"},{"id":"d","label":"Canal, codage, modulation, source"}],"answer":{"id":"c"},"display":"Source, codage, modulation, canal","explanation":"<p>Le message est d’abord codé, puis le signal modulé est envoyé dans le canal.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into public.assessments (id,title,description,kind,competency,question_count,pass_percent,duration_seconds,max_attempts,cooldown_minutes,prerequisites,grants,status) values ('final-modulation','Évaluation : Modulation et démodulation','Évaluation de fin de module, corrigée par le serveur.','course_final','modulation',5,70,1200,null,30,array['signaux']::text[],array[]::text[],'published') on conflict (id) do update set title=excluded.title, description=excluded.description, prerequisites=excluded.prerequisites, grants=excluded.grants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('modulation:mo-ambw','final-modulation','Modulation AM','numeric','[{"prompt":"<p>Un signal modulant de 3 kHz module une porteuse en AM. Calculez la largeur de bande, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":6,"rel":0.02},"display":"6 kHz","explanation":"<p>B = 2fm = 6 kHz.</p>"},{"prompt":"<p>Un signal modulant de 4,5 kHz module une porteuse en AM. Calculez la largeur de bande, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":9,"rel":0.02},"display":"9 kHz","explanation":"<p>B = 2fm = 9 kHz.</p>"},{"prompt":"<p>Un signal modulant de 5 kHz module une porteuse en AM. Calculez la largeur de bande, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":10,"rel":0.02},"display":"10 kHz","explanation":"<p>B = 2fm = 10 kHz.</p>"},{"prompt":"<p>Un signal modulant de 10 kHz module une porteuse en AM. Calculez la largeur de bande, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":20,"rel":0.02},"display":"20 kHz","explanation":"<p>B = 2fm = 20 kHz.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('modulation:mo-eff','final-modulation','Modulation AM','numeric','[{"prompt":"<p>Calculez le rendement en puissance d’une AM d’indice m = 0,3, <strong>en %</strong>.</p>","unit":"%","answer":{"value":4.30622009569378,"abs":0.5},"display":"4,306 %","explanation":"<p>η = m²/(2+m²) = 4,306 %.</p>"},{"prompt":"<p>Calculez le rendement en puissance d’une AM d’indice m = 0,5, <strong>en %</strong>.</p>","unit":"%","answer":{"value":11.11111111111111,"abs":0.5},"display":"11,11 %","explanation":"<p>η = m²/(2+m²) = 11,11 %.</p>"},{"prompt":"<p>Calculez le rendement en puissance d’une AM d’indice m = 0,8, <strong>en %</strong>.</p>","unit":"%","answer":{"value":24.242424242424246,"abs":0.5},"display":"24,24 %","explanation":"<p>η = m²/(2+m²) = 24,24 %.</p>"},{"prompt":"<p>Calculez le rendement en puissance d’une AM d’indice m = 1, <strong>en %</strong>.</p>","unit":"%","answer":{"value":33.33333333333333,"abs":0.5},"display":"33,33 %","explanation":"<p>η = m²/(2+m²) = 33,33 %.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('modulation:mo-carson','final-modulation','Modulation FM','numeric','[{"prompt":"<p>En FM, l’excursion est de 75 kHz et la fréquence modulante de 15 kHz. Calculez la largeur de bande de Carson, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":180,"rel":0.02},"display":"180 kHz","explanation":"<p>B ≈ 2(Δf + fm) = 180 kHz.</p>"},{"prompt":"<p>En FM, l’excursion est de 5 kHz et la fréquence modulante de 3 kHz. Calculez la largeur de bande de Carson, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":16,"rel":0.02},"display":"16 kHz","explanation":"<p>B ≈ 2(Δf + fm) = 16 kHz.</p>"},{"prompt":"<p>En FM, l’excursion est de 25 kHz et la fréquence modulante de 5 kHz. Calculez la largeur de bande de Carson, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":60,"rel":0.02},"display":"60 kHz","explanation":"<p>B ≈ 2(Δf + fm) = 60 kHz.</p>"},{"prompt":"<p>En FM, l’excursion est de 50 kHz et la fréquence modulante de 10 kHz. Calculez la largeur de bande de Carson, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":120,"rel":0.02},"display":"120 kHz","explanation":"<p>B ≈ 2(Δf + fm) = 120 kHz.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('modulation:mo-beta','final-modulation','Modulation FM','numeric','[{"prompt":"<p>Calculez l’indice de modulation β pour Δf = 75 kHz et fm = 15 kHz.</p>","unit":"","answer":{"value":5,"rel":0.02},"display":"5","explanation":"<p>β = Δf/fm = 5.</p>"},{"prompt":"<p>Calculez l’indice de modulation β pour Δf = 5 kHz et fm = 2,5 kHz.</p>","unit":"","answer":{"value":2,"rel":0.02},"display":"2","explanation":"<p>β = Δf/fm = 2.</p>"},{"prompt":"<p>Calculez l’indice de modulation β pour Δf = 30 kHz et fm = 10 kHz.</p>","unit":"","answer":{"value":3,"rel":0.02},"display":"3","explanation":"<p>β = Δf/fm = 3.</p>"},{"prompt":"<p>Calculez l’indice de modulation β pour Δf = 50 kHz et fm = 5 kHz.</p>","unit":"","answer":{"value":10,"rel":0.02},"display":"10","explanation":"<p>β = Δf/fm = 10.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('modulation:mo-psk','final-modulation','Modulations numériques','numeric','[{"prompt":"<p>Estimez la largeur de bande (lobe principal) d’une BPSK à 1 Mbit/s, <strong>en MHz</strong>.</p>","unit":"MHz","answer":{"value":2,"rel":0.02},"display":"2 MHz","explanation":"<p>B ≈ 2Rb = 2 MHz.</p>"},{"prompt":"<p>Estimez la largeur de bande (lobe principal) d’une BPSK à 2 Mbit/s, <strong>en MHz</strong>.</p>","unit":"MHz","answer":{"value":4,"rel":0.02},"display":"4 MHz","explanation":"<p>B ≈ 2Rb = 4 MHz.</p>"},{"prompt":"<p>Estimez la largeur de bande (lobe principal) d’une BPSK à 0,5 Mbit/s, <strong>en MHz</strong>.</p>","unit":"MHz","answer":{"value":1,"rel":0.02},"display":"1 MHz","explanation":"<p>B ≈ 2Rb = 1 MHz.</p>"},{"prompt":"<p>Estimez la largeur de bande (lobe principal) d’une BPSK à 10 Mbit/s, <strong>en MHz</strong>.</p>","unit":"MHz","answer":{"value":20,"rel":0.02},"display":"20 MHz","explanation":"<p>B ≈ 2Rb = 20 MHz.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('modulation:mo-over','final-modulation','Modulation AM','qcm','[{"prompt":"<p>Que provoque un indice de modulation AM supérieur à 1 ?</p>","options":[{"id":"a","label":"Une surmodulation qui déforme l’enveloppe"},{"id":"b","label":"Une meilleure qualité sonore"},{"id":"c","label":"Une baisse de la fréquence porteuse"},{"id":"d","label":"La suppression des bandes latérales"}],"answer":{"id":"a"},"display":"Une surmodulation qui déforme l’enveloppe","explanation":"<p>L’enveloppe passe par zéro et se replie : la détection d’enveloppe ne restitue plus le message.</p>"},{"prompt":"<p>Que provoque un indice de modulation AM supérieur à 1 ?</p>","options":[{"id":"a","label":"Une meilleure qualité sonore"},{"id":"b","label":"Une surmodulation qui déforme l’enveloppe"},{"id":"c","label":"Une baisse de la fréquence porteuse"},{"id":"d","label":"La suppression des bandes latérales"}],"answer":{"id":"b"},"display":"Une surmodulation qui déforme l’enveloppe","explanation":"<p>L’enveloppe passe par zéro et se replie : la détection d’enveloppe ne restitue plus le message.</p>"},{"prompt":"<p>Que provoque un indice de modulation AM supérieur à 1 ?</p>","options":[{"id":"a","label":"Une meilleure qualité sonore"},{"id":"b","label":"Une baisse de la fréquence porteuse"},{"id":"c","label":"Une surmodulation qui déforme l’enveloppe"},{"id":"d","label":"La suppression des bandes latérales"}],"answer":{"id":"c"},"display":"Une surmodulation qui déforme l’enveloppe","explanation":"<p>L’enveloppe passe par zéro et se replie : la détection d’enveloppe ne restitue plus le message.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
