insert into private.questions (id,assessment_id,skill,kind,variants) values ('ip:ip-net','final-ip','Adresse de réseau','text','[{"prompt":"<p>Quelle est l’adresse de réseau de 192.168.10.77/26 ?</p>","answer":{"accepted":["0.0.0.0"]},"display":"0.0.0.0","explanation":"<p>ET logique avec le masque /26 : 0.0.0.0.</p>"},{"prompt":"<p>Quelle est l’adresse de réseau de 10.20.30.40/20 ?</p>","answer":{"accepted":["0.0.0.0"]},"display":"0.0.0.0","explanation":"<p>ET logique avec le masque /20 : 0.0.0.0.</p>"},{"prompt":"<p>Quelle est l’adresse de réseau de 172.16.5.130/25 ?</p>","answer":{"accepted":["0.0.0.0"]},"display":"0.0.0.0","explanation":"<p>ET logique avec le masque /25 : 0.0.0.0.</p>"},{"prompt":"<p>Quelle est l’adresse de réseau de 192.168.1.200/27 ?</p>","answer":{"accepted":["0.0.0.0"]},"display":"0.0.0.0","explanation":"<p>ET logique avec le masque /27 : 0.0.0.0.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ip:ip-bc','final-ip','Adresse de diffusion','text','[{"prompt":"<p>Quelle est l’adresse de diffusion de 192.168.10.77/26 ?</p>","answer":{"accepted":["0.0.0.63"]},"display":"0.0.0.63","explanation":"<p>Tous les bits d’hôte à 1 : 0.0.0.63.</p>"},{"prompt":"<p>Quelle est l’adresse de diffusion de 10.0.5.1/22 ?</p>","answer":{"accepted":["0.0.3.255"]},"display":"0.0.3.255","explanation":"<p>Tous les bits d’hôte à 1 : 0.0.3.255.</p>"},{"prompt":"<p>Quelle est l’adresse de diffusion de 172.16.5.130/25 ?</p>","answer":{"accepted":["0.0.0.127"]},"display":"0.0.0.127","explanation":"<p>Tous les bits d’hôte à 1 : 0.0.0.127.</p>"},{"prompt":"<p>Quelle est l’adresse de diffusion de 192.168.1.200/28 ?</p>","answer":{"accepted":["0.0.0.15"]},"display":"0.0.0.15","explanation":"<p>Tous les bits d’hôte à 1 : 0.0.0.15.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ip:ip-host','final-ip','Plan d’adressage','numeric','[{"prompt":"<p>Combien d’hôtes utilisables contient un réseau /24 ?</p>","unit":"","answer":{"value":254,"abs":0.01},"display":"254","explanation":"<p>2^(32−24) − 2 = 254.</p>"},{"prompt":"<p>Combien d’hôtes utilisables contient un réseau /26 ?</p>","unit":"","answer":{"value":62,"abs":0.01},"display":"62","explanation":"<p>2^(32−26) − 2 = 62.</p>"},{"prompt":"<p>Combien d’hôtes utilisables contient un réseau /20 ?</p>","unit":"","answer":{"value":4094,"abs":0.01},"display":"4 094","explanation":"<p>2^(32−20) − 2 = 4094.</p>"},{"prompt":"<p>Combien d’hôtes utilisables contient un réseau /28 ?</p>","unit":"","answer":{"value":14,"abs":0.01},"display":"14","explanation":"<p>2^(32−28) − 2 = 14.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ip:ip-pfx','final-ip','Plan d’adressage','numeric','[{"prompt":"<p>Quel préfixe le plus long permet d’accueillir 50 hôtes ? Donnez le nombre après la barre oblique.</p>","unit":"","answer":{"value":26,"abs":0.01},"display":"26","explanation":"<p>/26 offre 62 hôtes.</p>"},{"prompt":"<p>Quel préfixe le plus long permet d’accueillir 500 hôtes ? Donnez le nombre après la barre oblique.</p>","unit":"","answer":{"value":23,"abs":0.01},"display":"23","explanation":"<p>/23 offre 510 hôtes.</p>"},{"prompt":"<p>Quel préfixe le plus long permet d’accueillir 12 hôtes ? Donnez le nombre après la barre oblique.</p>","unit":"","answer":{"value":28,"abs":0.01},"display":"28","explanation":"<p>/28 offre 14 hôtes.</p>"},{"prompt":"<p>Quel préfixe le plus long permet d’accueillir 1000 hôtes ? Donnez le nombre après la barre oblique.</p>","unit":"","answer":{"value":22,"abs":0.01},"display":"22","explanation":"<p>/22 offre 1022 hôtes.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ip:ip-mask','final-ip','Masques','text','[{"prompt":"<p>Écrivez le masque correspondant au préfixe /20 en notation décimale pointée.</p>","answer":{"accepted":["255.255.240.0"]},"display":"255.255.240.0","explanation":"<p>20 bits à 1 : 255.255.240.0.</p>"},{"prompt":"<p>Écrivez le masque correspondant au préfixe /26 en notation décimale pointée.</p>","answer":{"accepted":["255.255.255.192"]},"display":"255.255.255.192","explanation":"<p>26 bits à 1 : 255.255.255.192.</p>"},{"prompt":"<p>Écrivez le masque correspondant au préfixe /22 en notation décimale pointée.</p>","answer":{"accepted":["255.255.252.0"]},"display":"255.255.252.0","explanation":"<p>22 bits à 1 : 255.255.252.0.</p>"},{"prompt":"<p>Écrivez le masque correspondant au préfixe /28 en notation décimale pointée.</p>","answer":{"accepted":["255.255.255.240"]},"display":"255.255.255.240","explanation":"<p>28 bits à 1 : 255.255.255.240.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ip:ip-depannage','final-ip','Dépannage','qcm','[{"prompt":"<p>Scénario de dépannage : un poste joint les machines de son sous-réseau mais aucune machine extérieure. Ses paramètres IP et son masque sont corrects. Que vérifiez-vous d’abord ?</p>","options":[{"id":"a","label":"La passerelle par défaut configurée sur le poste"},{"id":"b","label":"La table ARP du serveur distant"},{"id":"c","label":"La longueur du câble réseau"},{"id":"d","label":"Le TTL des paquets reçus"}],"answer":{"id":"a"},"display":"La passerelle par défaut configurée sur le poste","explanation":"<p>Tout trafic hors du sous-réseau passe par la passerelle : si elle manque ou est fausse, seul le réseau local répond.</p>"},{"prompt":"<p>Scénario de dépannage : un poste joint les machines de son sous-réseau mais aucune machine extérieure. Ses paramètres IP et son masque sont corrects. Que vérifiez-vous d’abord ?</p>","options":[{"id":"a","label":"La table ARP du serveur distant"},{"id":"b","label":"La passerelle par défaut configurée sur le poste"},{"id":"c","label":"La longueur du câble réseau"},{"id":"d","label":"Le TTL des paquets reçus"}],"answer":{"id":"b"},"display":"La passerelle par défaut configurée sur le poste","explanation":"<p>Tout trafic hors du sous-réseau passe par la passerelle : si elle manque ou est fausse, seul le réseau local répond.</p>"},{"prompt":"<p>Scénario de dépannage : un poste joint les machines de son sous-réseau mais aucune machine extérieure. Ses paramètres IP et son masque sont corrects. Que vérifiez-vous d’abord ?</p>","options":[{"id":"a","label":"La table ARP du serveur distant"},{"id":"b","label":"La longueur du câble réseau"},{"id":"c","label":"La passerelle par défaut configurée sur le poste"},{"id":"d","label":"Le TTL des paquets reçus"}],"answer":{"id":"c"},"display":"La passerelle par défaut configurée sur le poste","explanation":"<p>Tout trafic hors du sous-réseau passe par la passerelle : si elle manque ou est fausse, seul le réseau local répond.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into public.assessments (id,title,description,kind,competency,question_count,pass_percent,duration_seconds,max_attempts,cooldown_minutes,prerequisites,grants,status) values ('placement-bases','Positionnement : bases scientifiques','Pour les apprenants qui maîtrisent déjà les circuits et les signaux.','placement',null,8,80,1500,2,1440,array[]::text[],array['circuits','signaux']::text[],'published') on conflict (id) do update set title=excluded.title, description=excluded.description, prerequisites=excluded.prerequisites, grants=excluded.grants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-bases:ci-ohm','placement-bases','Loi d’Ohm','numeric','[{"prompt":"<p>Une résistance de 470 Ω est alimentée sous 12 V. Calculez le courant, <strong>en mA</strong>.</p>","unit":"mA","answer":{"value":25.53191489361702,"rel":0.02},"display":"25,53 mA","explanation":"<p>I = U/R = 12 / 470 = 25,53 mA.</p>"},{"prompt":"<p>Une résistance de 220 Ω est alimentée sous 5 V. Calculez le courant, <strong>en mA</strong>.</p>","unit":"mA","answer":{"value":22.727272727272727,"rel":0.02},"display":"22,73 mA","explanation":"<p>I = U/R = 5 / 220 = 22,73 mA.</p>"},{"prompt":"<p>Une résistance de 1 000 Ω est alimentée sous 9 V. Calculez le courant, <strong>en mA</strong>.</p>","unit":"mA","answer":{"value":9,"rel":0.02},"display":"9 mA","explanation":"<p>I = U/R = 9 / 1 000 = 9 mA.</p>"},{"prompt":"<p>Une résistance de 680 Ω est alimentée sous 24 V. Calculez le courant, <strong>en mA</strong>.</p>","unit":"mA","answer":{"value":35.294117647058826,"rel":0.02},"display":"35,29 mA","explanation":"<p>I = U/R = 24 / 680 = 35,29 mA.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-bases:ci-par','placement-bases','Association de résistances','numeric','[{"prompt":"<p>Deux résistances de 100 Ω et 100 Ω sont en parallèle. Calculez la résistance équivalente, en Ω.</p>","unit":"Ω","answer":{"value":50,"rel":0.02},"display":"50 Ω","explanation":"<p>Req = R₁R₂/(R₁+R₂) = 50 Ω.</p>"},{"prompt":"<p>Deux résistances de 220 Ω et 330 Ω sont en parallèle. Calculez la résistance équivalente, en Ω.</p>","unit":"Ω","answer":{"value":132,"rel":0.02},"display":"132 Ω","explanation":"<p>Req = R₁R₂/(R₁+R₂) = 132 Ω.</p>"},{"prompt":"<p>Deux résistances de 1 000 Ω et 470 Ω sont en parallèle. Calculez la résistance équivalente, en Ω.</p>","unit":"Ω","answer":{"value":319.7278911564626,"rel":0.02},"display":"319,7 Ω","explanation":"<p>Req = R₁R₂/(R₁+R₂) = 319,7 Ω.</p>"},{"prompt":"<p>Deux résistances de 150 Ω et 680 Ω sont en parallèle. Calculez la résistance équivalente, en Ω.</p>","unit":"Ω","answer":{"value":122.89156626506025,"rel":0.02},"display":"122,9 Ω","explanation":"<p>Req = R₁R₂/(R₁+R₂) = 122,9 Ω.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-bases:ci-div','placement-bases','Diviseur de tension','numeric','[{"prompt":"<p>Un diviseur à vide est alimenté sous 12 V, avec R₁ = 1 000 Ω côté source et R₂ = 2 200 Ω côté masse. Calculez la tension aux bornes de R₂, en V.</p>","unit":"V","answer":{"value":8.25,"rel":0.02},"display":"8,25 V","explanation":"<p>U₂ = E·R₂/(R₁+R₂) = 8,25 V.</p>"},{"prompt":"<p>Un diviseur à vide est alimenté sous 9 V, avec R₁ = 470 Ω côté source et R₂ = 470 Ω côté masse. Calculez la tension aux bornes de R₂, en V.</p>","unit":"V","answer":{"value":4.5,"rel":0.02},"display":"4,5 V","explanation":"<p>U₂ = E·R₂/(R₁+R₂) = 4,5 V.</p>"},{"prompt":"<p>Un diviseur à vide est alimenté sous 5 V, avec R₁ = 3 300 Ω côté source et R₂ = 1 000 Ω côté masse. Calculez la tension aux bornes de R₂, en V.</p>","unit":"V","answer":{"value":1.1627906976744187,"rel":0.02},"display":"1,163 V","explanation":"<p>U₂ = E·R₂/(R₁+R₂) = 1,163 V.</p>"},{"prompt":"<p>Un diviseur à vide est alimenté sous 24 V, avec R₁ = 10 000 Ω côté source et R₂ = 4 700 Ω côté masse. Calculez la tension aux bornes de R₂, en V.</p>","unit":"V","answer":{"value":7.673469387755102,"rel":0.02},"display":"7,673 V","explanation":"<p>U₂ = E·R₂/(R₁+R₂) = 7,673 V.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-bases:ci-pow','placement-bases','Puissance','numeric','[{"prompt":"<p>Une résistance de 100 Ω est parcourue par 50 mA. Calculez la puissance dissipée, <strong>en mW</strong>.</p>","unit":"mW","answer":{"value":250,"rel":0.02},"display":"250 mW","explanation":"<p>P = R·I² = 250 mW.</p>"},{"prompt":"<p>Une résistance de 470 Ω est parcourue par 20 mA. Calculez la puissance dissipée, <strong>en mW</strong>.</p>","unit":"mW","answer":{"value":188,"rel":0.02},"display":"188 mW","explanation":"<p>P = R·I² = 188 mW.</p>"},{"prompt":"<p>Une résistance de 220 Ω est parcourue par 100 mA. Calculez la puissance dissipée, <strong>en mW</strong>.</p>","unit":"mW","answer":{"value":2200,"rel":0.02},"display":"2 200 mW","explanation":"<p>P = R·I² = 2 200 mW.</p>"},{"prompt":"<p>Une résistance de 1 000 Ω est parcourue par 10 mA. Calculez la puissance dissipée, <strong>en mW</strong>.</p>","unit":"mW","answer":{"value":100,"rel":0.02},"display":"100 mW","explanation":"<p>P = R·I² = 100 mW.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-bases:si-per','placement-bases','Période et fréquence','numeric','[{"prompt":"<p>Un signal sinusoïdal a une fréquence de 50 Hz. Calculez sa période, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":20,"rel":0.02},"display":"20 ms","explanation":"<p>T = 1/f = 20 ms.</p>"},{"prompt":"<p>Un signal sinusoïdal a une fréquence de 250 Hz. Calculez sa période, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":4,"rel":0.02},"display":"4 ms","explanation":"<p>T = 1/f = 4 ms.</p>"},{"prompt":"<p>Un signal sinusoïdal a une fréquence de 400 Hz. Calculez sa période, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":2.5,"rel":0.02},"display":"2,5 ms","explanation":"<p>T = 1/f = 2,5 ms.</p>"},{"prompt":"<p>Un signal sinusoïdal a une fréquence de 1 000 Hz. Calculez sa période, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":1,"rel":0.02},"display":"1 ms","explanation":"<p>T = 1/f = 1 ms.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-bases:si-freq','placement-bases','Période et fréquence','numeric','[{"prompt":"<p>Sur l’oscilloscope, un cycle dure 2,5 ms. Calculez la fréquence, en Hz.</p>","unit":"Hz","answer":{"value":400,"rel":0.02},"display":"400 Hz","explanation":"<p>f = 1/T = 400 Hz.</p>"},{"prompt":"<p>Sur l’oscilloscope, un cycle dure 4 ms. Calculez la fréquence, en Hz.</p>","unit":"Hz","answer":{"value":250,"rel":0.02},"display":"250 Hz","explanation":"<p>f = 1/T = 250 Hz.</p>"},{"prompt":"<p>Sur l’oscilloscope, un cycle dure 8 ms. Calculez la fréquence, en Hz.</p>","unit":"Hz","answer":{"value":125,"rel":0.02},"display":"125 Hz","explanation":"<p>f = 1/T = 125 Hz.</p>"},{"prompt":"<p>Sur l’oscilloscope, un cycle dure 20 ms. Calculez la fréquence, en Hz.</p>","unit":"Hz","answer":{"value":50,"rel":0.02},"display":"50 Hz","explanation":"<p>f = 1/T = 50 Hz.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-bases:si-puls','placement-bases','Pulsation','numeric','[{"prompt":"<p>Calculez la pulsation ω d’un signal de 50 Hz, en rad/s.</p>","unit":"rad/s","answer":{"value":314.1592653589793,"rel":0.02},"display":"314,2 rad/s","explanation":"<p>ω = 2πf = 314,2 rad/s.</p>"},{"prompt":"<p>Calculez la pulsation ω d’un signal de 100 Hz, en rad/s.</p>","unit":"rad/s","answer":{"value":628.3185307179587,"rel":0.02},"display":"628,3 rad/s","explanation":"<p>ω = 2πf = 628,3 rad/s.</p>"},{"prompt":"<p>Calculez la pulsation ω d’un signal de 159 Hz, en rad/s.</p>","unit":"rad/s","answer":{"value":999.0264638415542,"rel":0.02},"display":"999 rad/s","explanation":"<p>ω = 2πf = 999 rad/s.</p>"},{"prompt":"<p>Calculez la pulsation ω d’un signal de 500 Hz, en rad/s.</p>","unit":"rad/s","answer":{"value":3141.592653589793,"rel":0.02},"display":"3 142 rad/s","explanation":"<p>ω = 2πf = 3 142 rad/s.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-bases:si-val','placement-bases','Lecture d’un signal','numeric','[{"prompt":"<p>Pour x(t) = 2 sin(2π · 100 · t), calculez x à t = 1,25 ms, en volts.</p>","unit":"V","answer":{"value":1.414213562373095,"abs":0.03},"display":"1,414 V","explanation":"<p>x = 2 · sin(2π · 100 · 0,00125) = 1,414 V.</p>"},{"prompt":"<p>Pour x(t) = 4 sin(2π · 50 · t), calculez x à t = 2,5 ms, en volts.</p>","unit":"V","answer":{"value":2.82842712474619,"abs":0.03},"display":"2,828 V","explanation":"<p>x = 4 · sin(2π · 50 · 0,0025) = 2,828 V.</p>"},{"prompt":"<p>Pour x(t) = 3 sin(2π · 200 · t), calculez x à t = 0,5 ms, en volts.</p>","unit":"V","answer":{"value":1.7633557568774194,"abs":0.03},"display":"1,763 V","explanation":"<p>x = 3 · sin(2π · 200 · 0,0005) = 1,763 V.</p>"},{"prompt":"<p>Pour x(t) = 5 sin(2π · 125 · t), calculez x à t = 1 ms, en volts.</p>","unit":"V","answer":{"value":3.5355339059327373,"abs":0.03},"display":"3,536 V","explanation":"<p>x = 5 · sin(2π · 125 · 0,001) = 3,536 V.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
