insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-radio:em-lam','placement-radio','Longueur d’onde','numeric','[{"prompt":"<p>Calculez la longueur d’onde dans le vide d’une onde de 100 MHz, <strong>en cm</strong>.</p>","unit":"cm","answer":{"value":299.792458,"rel":0.02},"display":"299,8 cm","explanation":"<p>λ = c/f = 299,8 cm.</p>"},{"prompt":"<p>Calculez la longueur d’onde dans le vide d’une onde de 900 MHz, <strong>en cm</strong>.</p>","unit":"cm","answer":{"value":33.31027311111111,"rel":0.02},"display":"33,31 cm","explanation":"<p>λ = c/f = 33,31 cm.</p>"},{"prompt":"<p>Calculez la longueur d’onde dans le vide d’une onde de 2 400 MHz, <strong>en cm</strong>.</p>","unit":"cm","answer":{"value":12.491352416666667,"rel":0.02},"display":"12,49 cm","explanation":"<p>λ = c/f = 12,49 cm.</p>"},{"prompt":"<p>Calculez la longueur d’onde dans le vide d’une onde de 5 000 MHz, <strong>en cm</strong>.</p>","unit":"cm","answer":{"value":5.99584916,"rel":0.02},"display":"5,996 cm","explanation":"<p>λ = c/f = 5,996 cm.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-radio:em-coax','placement-radio','Vitesse dans un milieu','numeric','[{"prompt":"<p>Dans un câble de facteur de vitesse 0,66, calculez la longueur d’onde à 100 MHz, en mètres.</p>","unit":"m","answer":{"value":1.9786302228000001,"rel":0.02},"display":"1,979 m","explanation":"<p>λ = VF·c/f = 1,979 m.</p>"},{"prompt":"<p>Dans un câble de facteur de vitesse 0,66, calculez la longueur d’onde à 145 MHz, en mètres.</p>","unit":"m","answer":{"value":1.3645725674482758,"rel":0.02},"display":"1,365 m","explanation":"<p>λ = VF·c/f = 1,365 m.</p>"},{"prompt":"<p>Dans un câble de facteur de vitesse 0,85, calculez la longueur d’onde à 433 MHz, en mètres.</p>","unit":"m","answer":{"value":0.5885071346420323,"rel":0.02},"display":"0,5885 m","explanation":"<p>λ = VF·c/f = 0,5885 m.</p>"},{"prompt":"<p>Dans un câble de facteur de vitesse 0,85, calculez la longueur d’onde à 1 000 MHz, en mètres.</p>","unit":"m","answer":{"value":0.2548235893,"rel":0.02},"display":"0,2548 m","explanation":"<p>λ = VF·c/f = 0,2548 m.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-radio:em-freq','placement-radio','Longueur d’onde','numeric','[{"prompt":"<p>Une onde a une longueur d’onde de 3 m dans le vide. Calculez sa fréquence, <strong>en MHz</strong>.</p>","unit":"MHz","answer":{"value":99.93081933333333,"rel":0.02},"display":"99,93 MHz","explanation":"<p>f = c/λ = 99,93 MHz.</p>"},{"prompt":"<p>Une onde a une longueur d’onde de 0,33 m dans le vide. Calculez sa fréquence, <strong>en MHz</strong>.</p>","unit":"MHz","answer":{"value":908.4619939393939,"rel":0.02},"display":"908,5 MHz","explanation":"<p>f = c/λ = 908,5 MHz.</p>"},{"prompt":"<p>Une onde a une longueur d’onde de 0,125 m dans le vide. Calculez sa fréquence, <strong>en MHz</strong>.</p>","unit":"MHz","answer":{"value":2398.339664,"rel":0.02},"display":"2 398 MHz","explanation":"<p>f = c/λ = 2 398 MHz.</p>"},{"prompt":"<p>Une onde a une longueur d’onde de 0,06 m dans le vide. Calculez sa fréquence, <strong>en MHz</strong>.</p>","unit":"MHz","answer":{"value":4996.540966666667,"rel":0.02},"display":"4 997 MHz","explanation":"<p>f = c/λ = 4 997 MHz.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-radio:em-time','placement-radio','Vitesse dans un milieu','numeric','[{"prompt":"<p>Combien de temps une onde met-elle pour parcourir 3 000 m dans le vide ? Réponse <strong>en µs</strong>.</p>","unit":"µs","answer":{"value":10.00692285594456,"rel":0.02},"display":"10,01 µs","explanation":"<p>t = d/c = 10,01 µs.</p>"},{"prompt":"<p>Combien de temps une onde met-elle pour parcourir 36 000 m dans le vide ? Réponse <strong>en µs</strong>.</p>","unit":"µs","answer":{"value":120.08307427133474,"rel":0.02},"display":"120,1 µs","explanation":"<p>t = d/c = 120,1 µs.</p>"},{"prompt":"<p>Combien de temps une onde met-elle pour parcourir 150 m dans le vide ? Réponse <strong>en µs</strong>.</p>","unit":"µs","answer":{"value":0.500346142797228,"rel":0.02},"display":"0,5003 µs","explanation":"<p>t = d/c = 0,5003 µs.</p>"},{"prompt":"<p>Combien de temps une onde met-elle pour parcourir 1 200 m dans le vide ? Réponse <strong>en µs</strong>.</p>","unit":"µs","answer":{"value":4.002769142377824,"rel":0.02},"display":"4,003 µs","explanation":"<p>t = d/c = 4,003 µs.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-radio:an-dip','placement-radio','Dimensionner un dipôle','numeric','[{"prompt":"<p>Calculez la longueur théorique d’un dipôle demi-onde à 100 MHz, <strong>en cm</strong> (facteur de raccourcissement ignoré).</p>","unit":"cm","answer":{"value":149.896229,"rel":0.02},"display":"149,9 cm","explanation":"<p>L = λ/2 = c/(2f) = 149,9 cm.</p>"},{"prompt":"<p>Calculez la longueur théorique d’un dipôle demi-onde à 145 MHz, <strong>en cm</strong> (facteur de raccourcissement ignoré).</p>","unit":"cm","answer":{"value":103.3767096551724,"rel":0.02},"display":"103,4 cm","explanation":"<p>L = λ/2 = c/(2f) = 103,4 cm.</p>"},{"prompt":"<p>Calculez la longueur théorique d’un dipôle demi-onde à 433 MHz, <strong>en cm</strong> (facteur de raccourcissement ignoré).</p>","unit":"cm","answer":{"value":34.61806674364896,"rel":0.02},"display":"34,62 cm","explanation":"<p>L = λ/2 = c/(2f) = 34,62 cm.</p>"},{"prompt":"<p>Calculez la longueur théorique d’un dipôle demi-onde à 900 MHz, <strong>en cm</strong> (facteur de raccourcissement ignoré).</p>","unit":"cm","answer":{"value":16.655136555555554,"rel":0.02},"display":"16,66 cm","explanation":"<p>L = λ/2 = c/(2f) = 16,66 cm.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-radio:an-db','placement-radio','Gain','numeric','[{"prompt":"<p>Une antenne a un gain de 2 en rapport linéaire. Exprimez-le en dBi.</p>","unit":"dBi","answer":{"value":3.010299956639812,"abs":0.15},"display":"3,01 dBi","explanation":"<p>G = 10 log₁₀(2) = 3,01 dBi.</p>"},{"prompt":"<p>Une antenne a un gain de 4 en rapport linéaire. Exprimez-le en dBi.</p>","unit":"dBi","answer":{"value":6.020599913279624,"abs":0.15},"display":"6,021 dBi","explanation":"<p>G = 10 log₁₀(4) = 6,021 dBi.</p>"},{"prompt":"<p>Une antenne a un gain de 10 en rapport linéaire. Exprimez-le en dBi.</p>","unit":"dBi","answer":{"value":10,"abs":0.15},"display":"10 dBi","explanation":"<p>G = 10 log₁₀(10) = 10 dBi.</p>"},{"prompt":"<p>Une antenne a un gain de 50 en rapport linéaire. Exprimez-le en dBi.</p>","unit":"dBi","answer":{"value":16.989700043360187,"abs":0.15},"display":"16,99 dBi","explanation":"<p>G = 10 log₁₀(50) = 16,99 dBi.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-radio:an-area','placement-radio','Surface effective','numeric','[{"prompt":"<p>Calculez la surface effective d’une antenne de gain linéaire 1,64 à 0,9 GHz, <strong>en cm²</strong>.</p>","unit":"cm²","answer":{"value":144.8072716627551,"rel":0.02},"display":"144,8 cm²","explanation":"<p>Ae = G·λ²/(4π) = 144,8 cm².</p>"},{"prompt":"<p>Calculez la surface effective d’une antenne de gain linéaire 10 à 2,4 GHz, <strong>en cm²</strong>.</p>","unit":"cm²","answer":{"value":124.16782059496911,"rel":0.02},"display":"124,2 cm²","explanation":"<p>Ae = G·λ²/(4π) = 124,2 cm².</p>"},{"prompt":"<p>Calculez la surface effective d’une antenne de gain linéaire 4 à 1,8 GHz, <strong>en cm²</strong>.</p>","unit":"cm²","answer":{"value":88.29711686753359,"rel":0.02},"display":"88,3 cm²","explanation":"<p>Ae = G·λ²/(4π) = 88,3 cm².</p>"},{"prompt":"<p>Calculez la surface effective d’une antenne de gain linéaire 31,6 à 5 GHz, <strong>en cm²</strong>.</p>","unit":"cm²","answer":{"value":90.40212013365561,"rel":0.02},"display":"90,4 cm²","explanation":"<p>Ae = G·λ²/(4π) = 90,4 cm².</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-radio:an-pol','placement-radio','Polarisation','numeric','[{"prompt":"<p>Deux antennes à polarisation linéaire sont désalignées de 0°. Quelle fraction de la puissance est captée ? Réponse <strong>en %</strong>.</p>","unit":"%","answer":{"value":100,"abs":1},"display":"100 %","explanation":"<p>Fraction = cos²(0°) = 100 %.</p>"},{"prompt":"<p>Deux antennes à polarisation linéaire sont désalignées de 30°. Quelle fraction de la puissance est captée ? Réponse <strong>en %</strong>.</p>","unit":"%","answer":{"value":75.00000000000001,"abs":1},"display":"75 %","explanation":"<p>Fraction = cos²(30°) = 75 %.</p>"},{"prompt":"<p>Deux antennes à polarisation linéaire sont désalignées de 45°. Quelle fraction de la puissance est captée ? Réponse <strong>en %</strong>.</p>","unit":"%","answer":{"value":50.000000000000014,"abs":1},"display":"50 %","explanation":"<p>Fraction = cos²(45°) = 50 %.</p>"},{"prompt":"<p>Deux antennes à polarisation linéaire sont désalignées de 60°. Quelle fraction de la puissance est captée ? Réponse <strong>en %</strong>.</p>","unit":"%","answer":{"value":25.00000000000001,"abs":1},"display":"25 %","explanation":"<p>Fraction = cos²(60°) = 25 %.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-radio:pr-fspl','placement-radio','Espace libre','numeric','[{"prompt":"<p>Calculez la perte en espace libre sur 1 km à 900 MHz, en dB.</p>","unit":"dB","answer":{"value":91.53263341066986,"abs":0.5},"display":"91,53 dB","explanation":"<p>FSPL = 20 log₁₀(4πdf/c) = 91,53 dB.</p>"},{"prompt":"<p>Calculez la perte en espace libre sur 5 km à 2 400 MHz, en dB.</p>","unit":"dB","answer":{"value":114.03140814283586,"abs":0.5},"display":"114 dB","explanation":"<p>FSPL = 20 log₁₀(4πdf/c) = 114 dB.</p>"},{"prompt":"<p>Calculez la perte en espace libre sur 10 km à 100 MHz, en dB.</p>","unit":"dB","answer":{"value":92.44778322188337,"abs":0.5},"display":"92,45 dB","explanation":"<p>FSPL = 20 log₁₀(4πdf/c) = 92,45 dB.</p>"},{"prompt":"<p>Calculez la perte en espace libre sur 0,2 km à 5 000 MHz, en dB.</p>","unit":"dB","answer":{"value":92.44778322188337,"abs":0.5},"display":"92,45 dB","explanation":"<p>FSPL = 20 log₁₀(4πdf/c) = 92,45 dB.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-radio:pr-budget','placement-radio','Bilan de liaison','numeric','[{"prompt":"<p>Puissance émise 30 dBm, gains d’antennes 10 dBi et 2 dBi, perte de trajet 110 dB. Calculez la puissance reçue, en dBm.</p>","unit":"dBm","answer":{"value":-68,"abs":0.1},"display":"−68 dBm","explanation":"<p>Pr = Pe + Ge + Gr − L = −68 dBm.</p>"},{"prompt":"<p>Puissance émise 20 dBm, gains d’antennes 6 dBi et 6 dBi, perte de trajet 95 dB. Calculez la puissance reçue, en dBm.</p>","unit":"dBm","answer":{"value":-63,"abs":0.1},"display":"−63 dBm","explanation":"<p>Pr = Pe + Ge + Gr − L = −63 dBm.</p>"},{"prompt":"<p>Puissance émise 43 dBm, gains d’antennes 15 dBi et 0 dBi, perte de trajet 130 dB. Calculez la puissance reçue, en dBm.</p>","unit":"dBm","answer":{"value":-72,"abs":0.1},"display":"−72 dBm","explanation":"<p>Pr = Pe + Ge + Gr − L = −72 dBm.</p>"},{"prompt":"<p>Puissance émise 10 dBm, gains d’antennes 3 dBi et 3 dBi, perte de trajet 80 dB. Calculez la puissance reçue, en dBm.</p>","unit":"dBm","answer":{"value":-64,"abs":0.1},"display":"−64 dBm","explanation":"<p>Pr = Pe + Ge + Gr − L = −64 dBm.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-radio:pr-horizon','placement-radio','Horizon radio','numeric','[{"prompt":"<p>Avec des antennes à 30 m et 1,5 m (modèle 4/3 de la Terre), calculez l’horizon radio, <strong>en km</strong>.</p>","unit":"km","answer":{"value":27.612118239346188,"rel":0.03},"display":"27,61 km","explanation":"<p>d ≈ 4,12(√h₁ + √h₂) = 27,61 km.</p>"},{"prompt":"<p>Avec des antennes à 50 m et 10 m (modèle 4/3 de la Terre), calculez l’horizon radio, <strong>en km</strong>.</p>","unit":"km","answer":{"value":42.16138334477948,"rel":0.03},"display":"42,16 km","explanation":"<p>d ≈ 4,12(√h₁ + √h₂) = 42,16 km.</p>"},{"prompt":"<p>Avec des antennes à 100 m et 2 m (modèle 4/3 de la Terre), calculez l’horizon radio, <strong>en km</strong>.</p>","unit":"km","answer":{"value":47.02655987697715,"rel":0.03},"display":"47,03 km","explanation":"<p>d ≈ 4,12(√h₁ + √h₂) = 47,03 km.</p>"},{"prompt":"<p>Avec des antennes à 20 m et 20 m (modèle 4/3 de la Terre), calculez l’horizon radio, <strong>en km</strong>.</p>","unit":"km","answer":{"value":36.850400269196534,"rel":0.03},"display":"36,85 km","explanation":"<p>d ≈ 4,12(√h₁ + √h₂) = 36,85 km.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-radio:pr-fresnel','placement-radio','Zone de Fresnel','numeric','[{"prompt":"<p>À 900 MHz, un obstacle se trouve à 1 000 m de l’émetteur et 1 000 m du récepteur. Calculez le rayon de la première zone de Fresnel, en mètres.</p>","unit":"m","answer":{"value":12.90547812192774,"rel":0.03},"display":"12,91 m","explanation":"<p>r = √(λ·d₁·d₂/(d₁+d₂)) = 12,91 m.</p>"},{"prompt":"<p>À 2 400 MHz, un obstacle se trouve à 500 m de l’émetteur et 1 500 m du récepteur. Calculez le rayon de la première zone de Fresnel, en mètres.</p>","unit":"m","answer":{"value":6.844163320852301,"rel":0.03},"display":"6,844 m","explanation":"<p>r = √(λ·d₁·d₂/(d₁+d₂)) = 6,844 m.</p>"},{"prompt":"<p>À 5 000 MHz, un obstacle se trouve à 2 000 m de l’émetteur et 2 000 m du récepteur. Calculez le rayon de la première zone de Fresnel, en mètres.</p>","unit":"m","answer":{"value":7.743286873156644,"rel":0.03},"display":"7,743 m","explanation":"<p>r = √(λ·d₁·d₂/(d₁+d₂)) = 7,743 m.</p>"},{"prompt":"<p>À 100 MHz, un obstacle se trouve à 5 000 m de l’émetteur et 5 000 m du récepteur. Calculez le rayon de la première zone de Fresnel, en mètres.</p>","unit":"m","answer":{"value":86.57257908830023,"rel":0.03},"display":"86,57 m","explanation":"<p>r = √(λ·d₁·d₂/(d₁+d₂)) = 86,57 m.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into public.assessments (id,title,description,kind,competency,question_count,pass_percent,duration_seconds,max_attempts,cooldown_minutes,prerequisites,grants,status) values ('placement-transmission','Positionnement : transmission','Chaîne de transmission et modulation.','placement',null,10,80,1500,2,1440,array[]::text[],array['signaux','chaine','modulation']::text[],'published') on conflict (id) do update set title=excluded.title, description=excluded.description, prerequisites=excluded.prerequisites, grants=excluded.grants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-transmission:si-per','placement-transmission','Période et fréquence','numeric','[{"prompt":"<p>Un signal sinusoïdal a une fréquence de 50 Hz. Calculez sa période, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":20,"rel":0.02},"display":"20 ms","explanation":"<p>T = 1/f = 20 ms.</p>"},{"prompt":"<p>Un signal sinusoïdal a une fréquence de 250 Hz. Calculez sa période, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":4,"rel":0.02},"display":"4 ms","explanation":"<p>T = 1/f = 4 ms.</p>"},{"prompt":"<p>Un signal sinusoïdal a une fréquence de 400 Hz. Calculez sa période, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":2.5,"rel":0.02},"display":"2,5 ms","explanation":"<p>T = 1/f = 2,5 ms.</p>"},{"prompt":"<p>Un signal sinusoïdal a une fréquence de 1 000 Hz. Calculez sa période, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":1,"rel":0.02},"display":"1 ms","explanation":"<p>T = 1/f = 1 ms.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-transmission:si-freq','placement-transmission','Période et fréquence','numeric','[{"prompt":"<p>Sur l’oscilloscope, un cycle dure 2,5 ms. Calculez la fréquence, en Hz.</p>","unit":"Hz","answer":{"value":400,"rel":0.02},"display":"400 Hz","explanation":"<p>f = 1/T = 400 Hz.</p>"},{"prompt":"<p>Sur l’oscilloscope, un cycle dure 4 ms. Calculez la fréquence, en Hz.</p>","unit":"Hz","answer":{"value":250,"rel":0.02},"display":"250 Hz","explanation":"<p>f = 1/T = 250 Hz.</p>"},{"prompt":"<p>Sur l’oscilloscope, un cycle dure 8 ms. Calculez la fréquence, en Hz.</p>","unit":"Hz","answer":{"value":125,"rel":0.02},"display":"125 Hz","explanation":"<p>f = 1/T = 125 Hz.</p>"},{"prompt":"<p>Sur l’oscilloscope, un cycle dure 20 ms. Calculez la fréquence, en Hz.</p>","unit":"Hz","answer":{"value":50,"rel":0.02},"display":"50 Hz","explanation":"<p>f = 1/T = 50 Hz.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-transmission:si-puls','placement-transmission','Pulsation','numeric','[{"prompt":"<p>Calculez la pulsation ω d’un signal de 50 Hz, en rad/s.</p>","unit":"rad/s","answer":{"value":314.1592653589793,"rel":0.02},"display":"314,2 rad/s","explanation":"<p>ω = 2πf = 314,2 rad/s.</p>"},{"prompt":"<p>Calculez la pulsation ω d’un signal de 100 Hz, en rad/s.</p>","unit":"rad/s","answer":{"value":628.3185307179587,"rel":0.02},"display":"628,3 rad/s","explanation":"<p>ω = 2πf = 628,3 rad/s.</p>"},{"prompt":"<p>Calculez la pulsation ω d’un signal de 159 Hz, en rad/s.</p>","unit":"rad/s","answer":{"value":999.0264638415542,"rel":0.02},"display":"999 rad/s","explanation":"<p>ω = 2πf = 999 rad/s.</p>"},{"prompt":"<p>Calculez la pulsation ω d’un signal de 500 Hz, en rad/s.</p>","unit":"rad/s","answer":{"value":3141.592653589793,"rel":0.02},"display":"3 142 rad/s","explanation":"<p>ω = 2πf = 3 142 rad/s.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-transmission:si-val','placement-transmission','Lecture d’un signal','numeric','[{"prompt":"<p>Pour x(t) = 2 sin(2π · 100 · t), calculez x à t = 1,25 ms, en volts.</p>","unit":"V","answer":{"value":1.414213562373095,"abs":0.03},"display":"1,414 V","explanation":"<p>x = 2 · sin(2π · 100 · 0,00125) = 1,414 V.</p>"},{"prompt":"<p>Pour x(t) = 4 sin(2π · 50 · t), calculez x à t = 2,5 ms, en volts.</p>","unit":"V","answer":{"value":2.82842712474619,"abs":0.03},"display":"2,828 V","explanation":"<p>x = 4 · sin(2π · 50 · 0,0025) = 2,828 V.</p>"},{"prompt":"<p>Pour x(t) = 3 sin(2π · 200 · t), calculez x à t = 0,5 ms, en volts.</p>","unit":"V","answer":{"value":1.7633557568774194,"abs":0.03},"display":"1,763 V","explanation":"<p>x = 3 · sin(2π · 200 · 0,0005) = 1,763 V.</p>"},{"prompt":"<p>Pour x(t) = 5 sin(2π · 125 · t), calculez x à t = 1 ms, en volts.</p>","unit":"V","answer":{"value":3.5355339059327373,"abs":0.03},"display":"3,536 V","explanation":"<p>x = 5 · sin(2π · 125 · 0,001) = 3,536 V.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-transmission:ch-db','placement-transmission','Décibels','numeric','[{"prompt":"<p>Un rapport signal sur bruit vaut 3 dB. Donnez-le en rapport linéaire.</p>","unit":"","answer":{"value":1.9952623149688795,"rel":0.02},"display":"1,995","explanation":"<p>10^(3/10) = 1,995.</p>"},{"prompt":"<p>Un rapport signal sur bruit vaut 10 dB. Donnez-le en rapport linéaire.</p>","unit":"","answer":{"value":10,"rel":0.02},"display":"10","explanation":"<p>10^(10/10) = 10.</p>"},{"prompt":"<p>Un rapport signal sur bruit vaut 20 dB. Donnez-le en rapport linéaire.</p>","unit":"","answer":{"value":100,"rel":0.02},"display":"100","explanation":"<p>10^(20/10) = 100.</p>"},{"prompt":"<p>Un rapport signal sur bruit vaut 13 dB. Donnez-le en rapport linéaire.</p>","unit":"","answer":{"value":19.952623149688797,"rel":0.02},"display":"19,95","explanation":"<p>10^(13/10) = 19,95.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-transmission:ch-shannon','placement-transmission','Capacité de Shannon','numeric','[{"prompt":"<p>Calculez la capacité de Shannon d’un canal de 1 MHz avec un RSB de 10 dB, <strong>en Mbit/s</strong>.</p>","unit":"Mbit/s","answer":{"value":3.4594316186372973,"rel":0.02},"display":"3,459 Mbit/s","explanation":"<p>C = B log₂(1 + RSB) = 3,459 Mbit/s.</p>"},{"prompt":"<p>Calculez la capacité de Shannon d’un canal de 20 MHz avec un RSB de 20 dB, <strong>en Mbit/s</strong>.</p>","unit":"Mbit/s","answer":{"value":133.1642296550359,"rel":0.02},"display":"133,2 Mbit/s","explanation":"<p>C = B log₂(1 + RSB) = 133,2 Mbit/s.</p>"},{"prompt":"<p>Calculez la capacité de Shannon d’un canal de 5 MHz avec un RSB de 15 dB, <strong>en Mbit/s</strong>.</p>","unit":"Mbit/s","answer":{"value":25.139038366752597,"rel":0.02},"display":"25,14 Mbit/s","explanation":"<p>C = B log₂(1 + RSB) = 25,14 Mbit/s.</p>"},{"prompt":"<p>Calculez la capacité de Shannon d’un canal de 0,1 MHz avec un RSB de 30 dB, <strong>en Mbit/s</strong>.</p>","unit":"Mbit/s","answer":{"value":0.9967226258835993,"rel":0.02},"display":"0,9967 Mbit/s","explanation":"<p>C = B log₂(1 + RSB) = 0,9967 Mbit/s.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-transmission:ch-noise','placement-transmission','Bruit thermique','numeric','[{"prompt":"<p>Calculez la puissance de bruit thermique dans 1 MHz à 290 K, en dBm.</p>","unit":"dBm","answer":{"value":-113.97518719422811,"abs":0.5},"display":"−114 dBm","explanation":"<p>N = kTB, soit environ −174 + 10 log₁₀(B) = −114 dBm.</p>"},{"prompt":"<p>Calculez la puissance de bruit thermique dans 20 MHz à 290 K, en dBm.</p>","unit":"dBm","answer":{"value":-100.9648872375883,"abs":0.5},"display":"−101 dBm","explanation":"<p>N = kTB, soit environ −174 + 10 log₁₀(B) = −101 dBm.</p>"},{"prompt":"<p>Calculez la puissance de bruit thermique dans 0,2 MHz à 290 K, en dBm.</p>","unit":"dBm","answer":{"value":-120.9648872375883,"abs":0.5},"display":"−121 dBm","explanation":"<p>N = kTB, soit environ −174 + 10 log₁₀(B) = −121 dBm.</p>"},{"prompt":"<p>Calculez la puissance de bruit thermique dans 100 MHz à 290 K, en dBm.</p>","unit":"dBm","answer":{"value":-93.97518719422811,"abs":0.5},"display":"−93,98 dBm","explanation":"<p>N = kTB, soit environ −174 + 10 log₁₀(B) = −93,98 dBm.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-transmission:ch-rep','placement-transmission','Codage de canal','numeric','[{"prompt":"<p>Avec un code à répétition ×3, combien de bits sont transmis pour 100 bits utiles ?</p>","unit":"bits","answer":{"value":300,"abs":0.5},"display":"300 bits","explanation":"<p>Rendement 1/3 : 100 × 3 = 300 bits.</p>"},{"prompt":"<p>Avec un code à répétition ×3, combien de bits sont transmis pour 8 bits utiles ?</p>","unit":"bits","answer":{"value":24,"abs":0.5},"display":"24 bits","explanation":"<p>Rendement 1/3 : 8 × 3 = 24 bits.</p>"},{"prompt":"<p>Avec un code à répétition ×3, combien de bits sont transmis pour 1 000 bits utiles ?</p>","unit":"bits","answer":{"value":3000,"abs":0.5},"display":"3 000 bits","explanation":"<p>Rendement 1/3 : 1 000 × 3 = 3 000 bits.</p>"},{"prompt":"<p>Avec un code à répétition ×3, combien de bits sont transmis pour 56 bits utiles ?</p>","unit":"bits","answer":{"value":168,"abs":0.5},"display":"168 bits","explanation":"<p>Rendement 1/3 : 56 × 3 = 168 bits.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-transmission:mo-ambw','placement-transmission','Modulation AM','numeric','[{"prompt":"<p>Un signal modulant de 3 kHz module une porteuse en AM. Calculez la largeur de bande, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":6,"rel":0.02},"display":"6 kHz","explanation":"<p>B = 2fm = 6 kHz.</p>"},{"prompt":"<p>Un signal modulant de 4,5 kHz module une porteuse en AM. Calculez la largeur de bande, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":9,"rel":0.02},"display":"9 kHz","explanation":"<p>B = 2fm = 9 kHz.</p>"},{"prompt":"<p>Un signal modulant de 5 kHz module une porteuse en AM. Calculez la largeur de bande, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":10,"rel":0.02},"display":"10 kHz","explanation":"<p>B = 2fm = 10 kHz.</p>"},{"prompt":"<p>Un signal modulant de 10 kHz module une porteuse en AM. Calculez la largeur de bande, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":20,"rel":0.02},"display":"20 kHz","explanation":"<p>B = 2fm = 20 kHz.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-transmission:mo-eff','placement-transmission','Modulation AM','numeric','[{"prompt":"<p>Calculez le rendement en puissance d’une AM d’indice m = 0,3, <strong>en %</strong>.</p>","unit":"%","answer":{"value":4.30622009569378,"abs":0.5},"display":"4,306 %","explanation":"<p>η = m²/(2+m²) = 4,306 %.</p>"},{"prompt":"<p>Calculez le rendement en puissance d’une AM d’indice m = 0,5, <strong>en %</strong>.</p>","unit":"%","answer":{"value":11.11111111111111,"abs":0.5},"display":"11,11 %","explanation":"<p>η = m²/(2+m²) = 11,11 %.</p>"},{"prompt":"<p>Calculez le rendement en puissance d’une AM d’indice m = 0,8, <strong>en %</strong>.</p>","unit":"%","answer":{"value":24.242424242424246,"abs":0.5},"display":"24,24 %","explanation":"<p>η = m²/(2+m²) = 24,24 %.</p>"},{"prompt":"<p>Calculez le rendement en puissance d’une AM d’indice m = 1, <strong>en %</strong>.</p>","unit":"%","answer":{"value":33.33333333333333,"abs":0.5},"display":"33,33 %","explanation":"<p>η = m²/(2+m²) = 33,33 %.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-transmission:mo-carson','placement-transmission','Modulation FM','numeric','[{"prompt":"<p>En FM, l’excursion est de 75 kHz et la fréquence modulante de 15 kHz. Calculez la largeur de bande de Carson, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":180,"rel":0.02},"display":"180 kHz","explanation":"<p>B ≈ 2(Δf + fm) = 180 kHz.</p>"},{"prompt":"<p>En FM, l’excursion est de 5 kHz et la fréquence modulante de 3 kHz. Calculez la largeur de bande de Carson, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":16,"rel":0.02},"display":"16 kHz","explanation":"<p>B ≈ 2(Δf + fm) = 16 kHz.</p>"},{"prompt":"<p>En FM, l’excursion est de 25 kHz et la fréquence modulante de 5 kHz. Calculez la largeur de bande de Carson, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":60,"rel":0.02},"display":"60 kHz","explanation":"<p>B ≈ 2(Δf + fm) = 60 kHz.</p>"},{"prompt":"<p>En FM, l’excursion est de 50 kHz et la fréquence modulante de 10 kHz. Calculez la largeur de bande de Carson, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":120,"rel":0.02},"display":"120 kHz","explanation":"<p>B ≈ 2(Δf + fm) = 120 kHz.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-transmission:mo-beta','placement-transmission','Modulation FM','numeric','[{"prompt":"<p>Calculez l’indice de modulation β pour Δf = 75 kHz et fm = 15 kHz.</p>","unit":"","answer":{"value":5,"rel":0.02},"display":"5","explanation":"<p>β = Δf/fm = 5.</p>"},{"prompt":"<p>Calculez l’indice de modulation β pour Δf = 5 kHz et fm = 2,5 kHz.</p>","unit":"","answer":{"value":2,"rel":0.02},"display":"2","explanation":"<p>β = Δf/fm = 2.</p>"},{"prompt":"<p>Calculez l’indice de modulation β pour Δf = 30 kHz et fm = 10 kHz.</p>","unit":"","answer":{"value":3,"rel":0.02},"display":"3","explanation":"<p>β = Δf/fm = 3.</p>"},{"prompt":"<p>Calculez l’indice de modulation β pour Δf = 50 kHz et fm = 5 kHz.</p>","unit":"","answer":{"value":10,"rel":0.02},"display":"10","explanation":"<p>β = Δf/fm = 10.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into public.assessments (id,title,description,kind,competency,question_count,pass_percent,duration_seconds,max_attempts,cooldown_minutes,prerequisites,grants,status) values ('placement-reseaux','Positionnement : réseaux IP','Adressage IPv4, sous-réseaux, routage.','placement',null,4,80,1500,2,1440,array[]::text[],array['ip']::text[],'published') on conflict (id) do update set title=excluded.title, description=excluded.description, prerequisites=excluded.prerequisites, grants=excluded.grants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-reseaux:ip-net','placement-reseaux','Adresse de réseau','text','[{"prompt":"<p>Quelle est l’adresse de réseau de 192.168.10.77/26 ?</p>","answer":{"accepted":["0.0.0.0"]},"display":"0.0.0.0","explanation":"<p>ET logique avec le masque /26 : 0.0.0.0.</p>"},{"prompt":"<p>Quelle est l’adresse de réseau de 10.20.30.40/20 ?</p>","answer":{"accepted":["0.0.0.0"]},"display":"0.0.0.0","explanation":"<p>ET logique avec le masque /20 : 0.0.0.0.</p>"},{"prompt":"<p>Quelle est l’adresse de réseau de 172.16.5.130/25 ?</p>","answer":{"accepted":["0.0.0.0"]},"display":"0.0.0.0","explanation":"<p>ET logique avec le masque /25 : 0.0.0.0.</p>"},{"prompt":"<p>Quelle est l’adresse de réseau de 192.168.1.200/27 ?</p>","answer":{"accepted":["0.0.0.0"]},"display":"0.0.0.0","explanation":"<p>ET logique avec le masque /27 : 0.0.0.0.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-reseaux:ip-bc','placement-reseaux','Adresse de diffusion','text','[{"prompt":"<p>Quelle est l’adresse de diffusion de 192.168.10.77/26 ?</p>","answer":{"accepted":["0.0.0.63"]},"display":"0.0.0.63","explanation":"<p>Tous les bits d’hôte à 1 : 0.0.0.63.</p>"},{"prompt":"<p>Quelle est l’adresse de diffusion de 10.0.5.1/22 ?</p>","answer":{"accepted":["0.0.3.255"]},"display":"0.0.3.255","explanation":"<p>Tous les bits d’hôte à 1 : 0.0.3.255.</p>"},{"prompt":"<p>Quelle est l’adresse de diffusion de 172.16.5.130/25 ?</p>","answer":{"accepted":["0.0.0.127"]},"display":"0.0.0.127","explanation":"<p>Tous les bits d’hôte à 1 : 0.0.0.127.</p>"},{"prompt":"<p>Quelle est l’adresse de diffusion de 192.168.1.200/28 ?</p>","answer":{"accepted":["0.0.0.15"]},"display":"0.0.0.15","explanation":"<p>Tous les bits d’hôte à 1 : 0.0.0.15.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-reseaux:ip-host','placement-reseaux','Plan d’adressage','numeric','[{"prompt":"<p>Combien d’hôtes utilisables contient un réseau /24 ?</p>","unit":"","answer":{"value":254,"abs":0.01},"display":"254","explanation":"<p>2^(32−24) − 2 = 254.</p>"},{"prompt":"<p>Combien d’hôtes utilisables contient un réseau /26 ?</p>","unit":"","answer":{"value":62,"abs":0.01},"display":"62","explanation":"<p>2^(32−26) − 2 = 62.</p>"},{"prompt":"<p>Combien d’hôtes utilisables contient un réseau /20 ?</p>","unit":"","answer":{"value":4094,"abs":0.01},"display":"4 094","explanation":"<p>2^(32−20) − 2 = 4094.</p>"},{"prompt":"<p>Combien d’hôtes utilisables contient un réseau /28 ?</p>","unit":"","answer":{"value":14,"abs":0.01},"display":"14","explanation":"<p>2^(32−28) − 2 = 14.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-reseaux:ip-pfx','placement-reseaux','Plan d’adressage','numeric','[{"prompt":"<p>Quel préfixe le plus long permet d’accueillir 50 hôtes ? Donnez le nombre après la barre oblique.</p>","unit":"","answer":{"value":26,"abs":0.01},"display":"26","explanation":"<p>/26 offre 62 hôtes.</p>"},{"prompt":"<p>Quel préfixe le plus long permet d’accueillir 500 hôtes ? Donnez le nombre après la barre oblique.</p>","unit":"","answer":{"value":23,"abs":0.01},"display":"23","explanation":"<p>/23 offre 510 hôtes.</p>"},{"prompt":"<p>Quel préfixe le plus long permet d’accueillir 12 hôtes ? Donnez le nombre après la barre oblique.</p>","unit":"","answer":{"value":28,"abs":0.01},"display":"28","explanation":"<p>/28 offre 14 hôtes.</p>"},{"prompt":"<p>Quel préfixe le plus long permet d’accueillir 1000 hôtes ? Donnez le nombre après la barre oblique.</p>","unit":"","answer":{"value":22,"abs":0.01},"display":"22","explanation":"<p>/22 offre 1022 hôtes.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
